                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {citations.map((cite, idx) => {
                            let hostname = cite.uri;
                            try {
                                hostname = new URL(cite.uri).hostname;
