import React, { useState, useRef } from 'react';
import { generateArticleInfographic, generateInfographicFromFile } from '../services/geminiService';
import { Citation, ArticleHistoryItem } from '../types';
import { Link, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, ExternalLink, BookOpen, Clock, Maximize, Upload, FileText, X } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface ArticleToInfographicProps {
    history: ArticleHistoryItem[];
    onAddToHistory: (item: ArticleHistoryItem) => void;
}

const SKETCH_STYLES = [
    "Modern Editorial",
    "Fun & Playful",
    "Clean Minimalist",
    "Dark Mode Tech",
    "Custom"
];

const LANGUAGES = [
  { label: "Türkçe (Turkey)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "Arabic (Egypt)", value: "Arabic" },
  { label: "German (Germany)", value: "German" },
  { label: "Spanish (Mexico)", value: "Spanish" },
  { label: "French (France)", value: "French" },
  { label: "Hindi (India)", value: "Hindi" },
  { label: "Indonesian (Indonesia)", value: "Indonesian" },
  { label: "Italian (Italy)", value: "Italian" },
  { label: "Japanese (Japan)", value: "Japanese" },
  { label: "Korean (South Korea)", value: "Korean" },
  { label: "Portuguese (Brazil)", value: "Portuguese" },
  { label: "Russian (Russia)", value: "Russian" },
  { label: "Ukrainian (Ukraine)", value: "Ukrainian" },
  { label: "Vietnamese (Vietnam)", value: "Vietnamese" },
  { label: "Chinese (China)", value: "Chinese" },
];

const ArticleToInfographic: React.FC<ArticleToInfographicProps> = ({ history, onAddToHistory }) => {
  const [sourceType, setSourceType] = useState<'url' | 'file'>('url');
  const [urlInput, setUrlInput] = useState('');
  const [fileData, setFileData] = useState<{ base64: string; mime: string; name: string } | null>(null);
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Viewer State
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const addToHistory = (source: string, image: string, cites: Citation[]) => {
      let title = source;
      if (sourceType === 'url') {
          try { title = new URL(source).hostname; } catch(e) {}
      } else {
          title = fileData?.name || "Uploaded File";
      }

      const newItem: ArticleHistoryItem = {
          id: Date.now().toString(),
          title: title,
          url: sourceType === 'url' ? source : 'file-upload',
          imageData: image,
          citations: cites,
          date: new Date()
      };
      onAddToHistory(newItem);
  };

  const loadFromHistory = (item: ArticleHistoryItem) => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      if (item.url !== 'file-upload') {
          setSourceType('url');
          setUrlInput(item.url);
      } else {
          setSourceType('file');
      }
      setImageData(item.imageData);
      setCitations(item.citations);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = (reader.result as string).split(',')[1];
              setFileData({ base64, mime: file.type, name: file.name });
          };
          reader.readAsDataURL(file);
      }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (sourceType === 'url' && !urlInput.trim()) {
        setError("Please provide a valid URL.");
        return;
    }
    if (sourceType === 'file' && !fileData) {
        setError("Please upload a file.");
        return;
    }

    setLoading(true);
    setError(null);
    setImageData(null);
    setCitations([]);
    setLoadingStage('INITIALIZING...');

    try {
      const styleToUse = selectedStyle === 'Custom' ? customStyle : selectedStyle;
      let result;

      if (sourceType === 'url') {
          result = await generateArticleInfographic(urlInput, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage);
      } else {
          result = await generateInfographicFromFile(fileData!.base64, fileData!.mime, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage);
      }

      if (result && result.imageData) {
          setImageData(result.imageData);
          setCitations(result.citations || []);
          addToHistory(sourceType === 'url' ? urlInput : fileData!.name, result.imageData, result.citations || []);
      } else {
          throw new Error("Failed to generate infographic. Please try another source or style.");
      }
    } catch (err: any) {
      setError(err.message || "An unexpected error occurred.");
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 mb-20">

      {fullScreenImage && (
          <ImageViewer 
            src={fullScreenImage.src} 
            alt={fullScreenImage.alt} 
            onClose={() => setFullScreenImage(null)} 
          />
      )}

      {/* Hero Section */}
      <div className="text-center max-w-3xl mx-auto space-y-6">
        <h2 className="text-5xl md:text-6xl font-extrabold tracking-tight text-transparent bg-clip-text bg-gradient-to-b from-emerald-200 via-teal-200 to-slate-500 font-sans">
          Site<span className="text-emerald-400">Sketch</span>.
        </h2>
        <p className="text-slate-400 text-lg md:text-xl font-light tracking-wide">
          Turn any link or document into a stunning, easy-to-digest infographic.
        </p>
      </div>

      {/* Source Selector Tabs */}
      <div className="flex justify-center -mb-6">
          <div className="bg-slate-900/50 border border-white/5 p-1 rounded-xl flex gap-1 z-20">
              <button 
                onClick={() => setSourceType('url')}
