                              <div className="flex items-center gap-1.5 mt-2 text-slate-600 group-hover:text-slate-400 transition-colors">
                                  <Calendar className="w-3 h-3" />
                                  <span className="text-[9px] font-mono">{new Date(item.date).toLocaleDateString()}</span>
                              </div>
                          </div>
                      </button>
                  ))}
              </div>
          </div>
      )}
    </div>
  );
};

