                        history={articleHistory} 
                        onAddToHistory={handleAddArticleHistory}
                    />
                </div>
            )}
        </div>
      </main>

      <footer className="py-8 mt-auto border-t border-white/5 bg-slate-950/50">
        <div className="max-w-7xl mx-auto text-center px-4 space-y-2">
          <p className="text-xs font-mono text-slate-600">
            <span className="text-orange-500/70">link</span>:<span className="text-emerald-500/70">ink</span>$ Nano Banana Pro ile Güçlendirildi
          </p>
          <p className="text-xs font-mono text-slate-500">
            <a href="https://www.thirdhand.com.tr" target="_blank" rel="noopener noreferrer" className="text-orange-400 hover:text-orange-300 transition-colors underline decoration-orange-500/30 underline-offset-4 font-bold">thirdhand</a> AI tarafından yapılmıştır
          </p>
        </div>
      </footer>
    </div>
  );
};

export default App;

