        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: {
                parts: [
                    { inlineData: { data: fileBase64, mimeType } },
                    { text: analysisPrompt }
                ]
            }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        console.error("File analysis failed:", e);
        throw new Error("Dosya analiz edilemedi.");
    }

    return await finalizeInfographic(structuralSummary, style, onProgress, language);
}

async function finalizeInfographic(
    structuralSummary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR VE OLUŞTURULUYOR...");

    let styleGuidelines = "";
    switch (style) {
        case "Fun & Playful":
        case "Eğlenceli ve Canlı":
            styleGuidelines = `STYLE: Fun, playful, vibrant 2D vector illustrations. Use bright colors, rounded shapes, and a friendly tone.`;
            break;
        case "Temiz Minimalist":
        case "Clean Minimalist":
            styleGuidelines = `STYLE: Ultra-minimalist. Lots of whitespace, thin lines, limited color palette (1-2 accent colors max). Very sophisticated and airy.`;
            break;
        case "Minimalist Beyaz":
            styleGuidelines = `STYLE: Bright, high-contrast clinical white style. Pure white background, bold sharp black typography, grey accents. Very modern and expensive look.`;
            break;
        case "Dark Mode Tech":
        case "Koyu Mod Teknoloji":
            styleGuidelines = `STYLE: Dark mode technical aesthetic. Dark slate/black background with bright, glowing accent colors (cyan, lime green) for data points.`;
            break;
        case "Modern Editorial":
        case "Modern Editoryal":
            styleGuidelines = `STYLE: Modern, flat vector illustration style. Clean, professional, and editorial (like a high-end tech magazine). Cohesive, mature color palette.`;
            break;
        default:
             if (style && style !== "Custom" && style !== "Özel") {
                styleGuidelines = `STYLE: Custom User Style: "${style}".`;
             } else {
                styleGuidelines = `STYLE: Modern, flat vector illustration style. Clean, professional, and editorial (like a high-end tech magazine). Cohesive, mature color palette.`;
             }
            break;
    }

    const imagePrompt = `Create a professional, high-quality educational infographic based strictly on this structured content plan:
    ${structuralSummary}
    VISUAL DESIGN RULES:
    - ${styleGuidelines}
    - LANGUAGE: The text within the infographic MUST be written in ${language}.
    - TYPOGRAPHY: Clean, highly readable sans-serif fonts. The headline must be prominent at the top.
    - CONTENT: Use actual text from the plan, no placeholders.
    - GOAL: Informative and readable as a standalone graphic.`;

    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: { parts: [{ text: imagePrompt }] },
        config: { responseModalities: [Modality.IMAGE] },
    });

    let imageData = null;
    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
        for (const part of parts) {
            if (part.inlineData && part.inlineData.data) {
                imageData = part.inlineData.data;
                break;
            }
        }
    }
    return { imageData, citations: [] };
}

