import React, { useState } from 'react';
import { fetchRepoFileTree } from '../services/githubService';
import { generateInfographic } from '../services/geminiService';
import { RepoFileTree, ViewMode, RepoHistoryItem } from '../types';
import { AlertCircle, Loader2, Layers, Box, Download, Sparkles, Command, Palette, Globe, Clock, Maximize, KeyRound, Layout, LayoutHorizontal } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface RepoAnalyzerProps {
  onNavigate: (mode: ViewMode, data?: any) => void;
  history: RepoHistoryItem[];
  onAddToHistory: (item: RepoHistoryItem) => void;
}

const FLOW_STYLES = [
    "Modern Veri Akışı",
    "El Çizimi Blueprint",
    "Kurumsal Beyaz",
    "Neon Siberpunk",
    "Özel"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "Deutsch (Germany)", value: "German" },
];

const RepoAnalyzer: React.FC<RepoAnalyzerProps> = ({ onNavigate, history, onAddToHistory }) => {
  const [repoInput, setRepoInput] = useState('');
  const [selectedStyle, setSelectedStyle] = useState(FLOW_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("16:9");
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState<string>('');

  const [infographicData, setInfographicData] = useState<string | null>(null);
  const [infographic3DData, setInfographic3DData] = useState<string | null>(null);
  const [generating3D, setGenerating3D] = useState(false);
  const [currentFileTree, setCurrentFileTree] = useState<RepoFileTree[] | null>(null);
  const [currentRepoName, setCurrentRepoName] = useState<string>('');

  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const parseRepoInput = (input: string): { owner: string, repo: string } | null => {
    const cleanInput = input.trim().replace(/\/$/, '');
    try {
      const url = new URL(cleanInput);
      if (url.hostname === 'github.com') {
        const parts = url.pathname.split('/').filter(Boolean);
        if (parts.length >= 2) return { owner: parts[0], repo: parts[1] };
      }
    } catch (e) { }
    const parts = cleanInput.split('/');
    if (parts.length === 2 && parts[0] && parts[1]) return { owner: parts[0], repo: parts[1] };
    return null;
  };

  const addToHistory = (repoName: string, imageData: string, is3D: boolean, style: string) => {
     const newItem: RepoHistoryItem = {
         id: Date.now().toString(),
         repoName,
         imageData,
         is3D,
         style,
         date: new Date()
     };
     onAddToHistory(newItem);
  };

  const handleApiError = (err: any) => {
      if (err.message && err.message.includes("Requested entity was not found")) {
          const confirmSwitch = window.confirm(
              "ÖDEME GEREKLİ: Mevcut API anahtarı bu modelleri kullanma yetkisine sahip değil.\n\n" +
              "Bu özellik ücretli bir Google Cloud projesi gerektirir."
          );
          if (confirmSwitch) {
              window.location.reload();
          }
      }
      setError(err.message || 'Analiz sırasında beklenmedik bir hata oluştu.');
  }

  const handleAnalyze = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setInfographicData(null);
    setInfographic3DData(null);
    setCurrentFileTree(null);

    const repoDetails = parseRepoInput(repoInput);
    if (!repoDetails) {
      setError('Geçersiz format. "kullanici/depo" kullanın.');
      return;
    }

    setLoading(true);
    setCurrentRepoName(repoDetails.repo);
    try {
      setLoadingStage('GITHUB\'A BAĞLANILIYOR');
      const fileTree = await fetchRepoFileTree(repoDetails.owner, repoDetails.repo);

      if (fileTree.length === 0) throw new Error('Bu depoda ilgili kod dosyası bulunamadı.');
      setCurrentFileTree(fileTree);

      setLoadingStage('YAPI ANALİZ EDİLİYOR VE OLUŞTURULUYOR');

      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      const infographicBase64 = await generateInfographic(repoDetails.repo, fileTree, styleToUse, false, selectedLanguage, aspectRatio);

      if (infographicBase64) {
        setInfographicData(infographicBase64);
        addToHistory(repoDetails.repo, infographicBase64, false, styleToUse);
      } else {
          throw new Error("Görsel oluşturulamadı.");
      }

    } catch (err: any) {
      handleApiError(err);
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  const handleGenerate3D = async () => {
    if (!currentFileTree || !currentRepoName) return;
    setGenerating3D(true);
    try {
      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      const data = await generateInfographic(currentRepoName, currentFileTree, styleToUse, true, selectedLanguage, "16:9");
      if (data) {
          setInfographic3DData(data);
          addToHistory(currentRepoName, data, true, styleToUse);
      }
    } catch (err: any) {
      handleApiError(err);
    } finally {
      setGenerating3D(false);
    }
  };

  const loadFromHistory = (item: RepoHistoryItem) => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setCurrentRepoName(item.repoName);
      if (item.is3D) {
          setInfographic3DData(item.imageData);
      } else {
          setInfographicData(item.imageData);
          setInfographic3DData(null);
      }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-12 mb-20">

      {fullScreenImage && (
          <ImageViewer 
            src={fullScreenImage.src} 
            alt={fullScreenImage.alt} 
            onClose={() => setFullScreenImage(null)} 
          />
      )}

      {/* Hero Section */}
      <div className="text-center max-w-4xl mx-auto space-y-6">
        <h2 className="text-5xl md:text-7xl font-extrabold tracking-tight text-white font-sans leading-tight">
          Depo <span className="text-orange-500">Mimarisi</span>.
        </h2>
        <p className="text-slate-400 text-lg md:text-xl font-light tracking-wide">
          2K Ultra Netlikte Teknik Diyagramlar.
        </p>
      </div>

      {/* Input Section */}
      <div className="max-w-3xl mx-auto relative z-10">
        <form onSubmit={handleAnalyze} className="glass-panel rounded-3xl p-3 bg-white/5 border-white/20 transition-all focus-within:ring-2 focus-within:ring-white focus-within:border-white shadow-2xl">
          <div className="flex items-center p-2">
             <div className="pl-4 text-white/50">
                <Command className="w-6 h-6" />
             </div>
             <input
                type="text"
                value={repoInput}
                onChange={(e) => setRepoInput(e.target.value)}
                placeholder="kullanici/depo"
                className="w-full bg-transparent border-none text-white placeholder:text-slate-700 focus:ring-0 text-xl px-4 py-3 font-mono"
              />
              <div className="pr-2">
                <button
                type="submit"
                disabled={loading || !repoInput.trim()}
                className="px-6 py-3 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-2xl font-black transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2 font-mono text-sm tracking-widest"
                >
                {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : "ANALİZ_ET"}
                </button>
             </div>
          </div>

          <div className="mt-4 pt-4 border-t border-white/10 px-4 pb-2 grid md:grid-cols-2 gap-6">
             <div className="space-y-4">
                 <div className="flex items-center gap-2 text-white/40 font-mono text-[10px] uppercase tracking-widest">
                     <Palette className="w-4 h-4" /> Görsel Stil
                 </div>
                 <div className="flex flex-wrap gap-2">
                     {FLOW_STYLES.map(style => (
                         <button
                            key={style}
                            type="button"
                            onClick={() => setSelectedStyle(style)}
                            className={`text-[11px] px-3 py-1.5 rounded-lg font-mono transition-all border ${
                                selectedStyle === style 
                                ? 'bg-white text-slate-950 border-white font-bold' 
                                : 'bg-white/5 text-slate-500 border-white/10 hover:border-white/30 hover:text-white'
                            }`}
                         >
                             {style}
                         </button>
                     ))}
                 </div>
             </div>

             <div className="space-y-4">
                 <div className="flex items-center gap-2 text-orange-400 font-mono text-[10px] uppercase tracking-widest">
                     <Layout className="w-4 h-4" /> Format & Dil
                 </div>
                 <div className="flex gap-2">
                    <button
                        type="button"
                        onClick={() => setAspectRatio("9:16")}
                        className={`flex-1 py-2 px-3 rounded-xl font-mono text-[10px] transition-all border flex items-center justify-center gap-2 ${
                            aspectRatio === "9:16" 
                            ? 'bg-orange-500 text-white border-orange-500 font-bold' 
                            : 'bg-white/5 text-slate-500 border-white/10 hover:border-white/30'
                        }`}
                    >
                        <Layout className="w-3 h-3" /> DİKEY
                    </button>
                    <button
                        type="button"
                        onClick={() => setAspectRatio("16:9")}
                        className={`flex-1 py-2 px-3 rounded-xl font-mono text-[10px] transition-all border flex items-center justify-center gap-2 ${
                            aspectRatio === "16:9" 
                            ? 'bg-orange-500 text-white border-orange-500 font-bold' 
                            : 'bg-white/5 text-slate-500 border-white/10 hover:border-white/30'
                        }`}
                    >
                        <LayoutHorizontal className="w-3 h-3" /> YATAY
                    </button>
                 </div>
                 <div className="flex items-center gap-2 bg-slate-900 border border-white/10 rounded-xl px-3 py-2">
                    <Globe className="w-4 h-4 text-white/40 shrink-0" />
                    <select
                        value={selectedLanguage}
                        onChange={(e) => setSelectedLanguage(e.target.value)}
                        className="bg-transparent border-none text-xs text-white focus:ring-0 p-0 font-mono cursor-pointer flex-1"
                    >
                        {LANGUAGES.map((lang) => (
                        <option key={lang.value} value={lang.value} className="bg-slate-900 text-slate-300">
                            {lang.label}
                        </option>
                        ))}
                    </select>
                 </div>
             </div>
          </div>
        </form>
      </div>

      {loading && (
        <LoadingState message={loadingStage} type="repo" />
      )}

      {infographicData && !loading && (
        <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="glass-panel rounded-3xl p-2 bg-white/5 border-white/20 shadow-2xl">
                 <div className="px-6 py-4 flex items-center justify-between border-b border-white/10 mb-2 gap-4">
                    <h3 className="text-sm font-bold text-white flex items-center gap-2 font-mono uppercase tracking-widest">
                      <Layers className="w-4 h-4 text-white" /> Akış Diyagramı (2K)
                    </h3>
                    <div className="flex items-center gap-2">
                      <button 
                        onClick={() => setFullScreenImage({src: `data:image/png;base64,${infographicData}`, alt: `${currentRepoName} 2D`})}
                        className="p-2 hover:bg-white/10 rounded-xl text-slate-400 hover:text-white transition-all"
                      >
                        <Maximize className="w-5 h-5" />
                      </button>
                      <a href={`data:image/png;base64,${infographicData}`} download={`${currentRepoName}-2d.png`} className="bg-white text-slate-950 hover:bg-white/80 transition-all font-mono px-4 py-2 rounded-xl text-xs font-bold shadow-lg flex items-center gap-2">
                        <Download className="w-4 h-4" /> İNDİR
                      </a>
                    </div>
                </div>
                <div className={`rounded-2xl overflow-hidden bg-white relative border border-white/10 mx-auto ${aspectRatio === "16:9" ? "max-w-4xl" : "max-w-md"}`}>
                    <img src={`data:image/png;base64,${infographicData}`} alt="Diyagram" className="w-full h-auto object-cover relative z-10" />
                </div>
              </div>

              <div className="glass-panel rounded-3xl p-2 bg-white/5 border-white/20 shadow-2xl flex flex-col">
                 <div className="px-6 py-4 flex items-center justify-between border-b border-white/10 mb-2 shrink-0 gap-4">
                    <h3 className="text-sm font-bold text-white flex items-center gap-2 font-mono uppercase tracking-widest">
                      <Box className="w-4 h-4 text-orange-500" /> Holografik Model (3D)
                    </h3>
                </div>

                <div className="flex-1 rounded-2xl overflow-hidden bg-slate-900/50 relative flex items-center justify-center min-h-[400px]">
                  {infographic3DData ? (
                      <div className="w-full h-full flex items-center justify-center">
                         <img src={`data:image/png;base64,${infographic3DData}`} alt="3D Model" className="w-full h-full object-cover animate-in fade-in" />
                      </div>
                  ) : generating3D ? (
                    <div className="flex flex-col items-center justify-center gap-6 p-8 text-center animate-in fade-in">
                         <Loader2 className="w-12 h-12 animate-spin text-orange-500" />
                         <p className="text-orange-400 font-mono text-sm animate-pulse tracking-widest uppercase">HOLOGRAFİK MODEL OLUŞTURULUYOR...</p>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center justify-center gap-8 p-12 text-center">
                        <div className="w-20 h-20 bg-orange-500/10 rounded-3xl flex items-center justify-center border border-orange-500/20 shadow-neon-orange">
                            <Box className="w-10 h-10 text-orange-500" />
                        </div>
                        <button 
                          onClick={handleGenerate3D}
                          className="px-8 py-4 bg-orange-500 text-white hover:bg-orange-600 rounded-2xl font-black transition-all flex items-center gap-3 font-mono text-base shadow-xl"
                        >
                          <Sparkles className="w-5 h-5" />
                          3D_MODEL_OLUŞTUR
                        </button>
                    </div>
                  )}
                </div>
              </div>
          </div>
        </div>
      )}
    </div>
  );
};

