import React, { useState, useRef } from 'react';
import { generateArticleInfographic, generateInfographicFromFile, generateInfographicFromText } from '../services/geminiService';
import { Citation, ArticleHistoryItem } from '../types';
import { Link, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, ExternalLink, BookOpen, Clock, Maximize, Upload, FileText, X, Calendar, FileType, AlignLeft, Monitor, Smartphone } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface ArticleToInfographicProps {
    history: ArticleHistoryItem[];
    onAddToHistory: (item: ArticleHistoryItem) => void;
}

const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Temiz Minimalist",
    "Koyu Mod Teknoloji",
    "Özel"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "German (Germany)", value: "German" },
  { label: "Spanish (Mexico)", value: "Spanish" },
  { label: "French (France)", value: "French" },
];

const ArticleToInfographic: React.FC<ArticleToInfographicProps> = ({ history, onAddToHistory }) => {
  const [sourceType, setSourceType] = useState<'url' | 'file' | 'text'>('url');
  const [urlInput, setUrlInput] = useState('');
  const [textInput, setTextInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("9:16");
  const [fileData, setFileData] = useState<{ base64: string; mime: string; name: string; size: number } | null>(null);
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const addToHistory = (source: string, image: string, cites: Citation[]) => {
      let title = source;
      if (sourceType === 'url') {
          try { title = new URL(source).hostname; } catch(e) {}
      } else if (sourceType === 'file') {
          title = fileData?.name || "Yüklenen Dosya";
      } else {
          title = textInput.substring(0, 20) + "...";
      }

      const newItem: ArticleHistoryItem = {
          id: Date.now().toString(),
          title: title,
          url: sourceType === 'url' ? source : sourceType === 'file' ? 'file-upload' : 'raw-text',
          imageData: image,
          citations: cites,
          date: new Date()
      };
      onAddToHistory(newItem);
  };

  const loadFromHistory = (item: ArticleHistoryItem) => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      if (item.url === 'raw-text') {
          setSourceType('text');
      } else if (item.url === 'file-upload') {
          setSourceType('file');
      } else {
          setSourceType('url');
          setUrlInput(item.url);
      }
      setImageData(item.imageData);
      setCitations(item.citations);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          if (file.size > 15 * 1024 * 1024) {
              setError("Dosya boyutu 15MB limitini aşıyor.");
              return;
          }
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = (reader.result as string).split(',')[1];
              setFileData({ base64, mime: file.type, name: file.name, size: file.size });
              setError(null);
          };
          reader.readAsDataURL(file);
      }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (sourceType === 'url' && !urlInput.trim()) {
        setError("Lütfen geçerli bir URL girin.");
        return;
    }
    if (sourceType === 'file' && !fileData) {
        setError("Lütfen bir dosya yükleyin.");
        return;
    }
    if (sourceType === 'text' && !textInput.trim()) {
        setError("Lütfen metin girin.");
        return;
    }

    setLoading(true);
    setError(null);
    setImageData(null);
    setCitations([]);
    setLoadingStage('BAŞLATILIYOR...');

    try {
      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      let result;

      if (sourceType === 'url') {
          result = await generateArticleInfographic(urlInput, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      } else if (sourceType === 'file') {
          result = await generateInfographicFromFile(fileData!.base64, fileData!.mime, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      } else {
          result = await generateInfographicFromText(textInput, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      }

      if (result && result.imageData) {
          setImageData(result.imageData);
          setCitations(result.citations || []);
          addToHistory(sourceType === 'url' ? urlInput : sourceType === 'file' ? fileData!.name : textInput, result.imageData, result.citations || []);
      } else {
          throw new Error("İnfografik oluşturulamadı. Lütfen farklı bir stil deneyin.");
      }
    } catch (err: any) {
      setError(err.message || "Beklenmedik bir hata oluştu.");
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  const formatFileSize = (bytes: number) => {
      if (bytes === 0) return '0 Bayt';
      const k = 1024;
      const sizes = ['Bayt', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 mb-20">

      {fullScreenImage && (
          <ImageViewer 
            src={fullScreenImage.src} 
            alt={fullScreenImage.alt} 
            onClose={() => setFullScreenImage(null)} 
          />
      )}

      {/* Hero Section */}
      <div className="text-center max-w-3xl mx-auto space-y-6">
        <h2 className="text-5xl md:text-6xl font-extrabold tracking-tight text-white font-sans">
          Site<span className="text-orange-500">Taslağı</span>.
        </h2>
        <p className="text-slate-400 text-lg md:text-xl font-light tracking-wide">
          2K Çözünürlükte Yatay veya Dikey İnfografikler Oluşturun.
        </p>
      </div>

      {/* Source Selector Tabs */}
      <div className="flex justify-center -mb-6">
          <div className="bg-white/5 border border-white/20 p-1 rounded-xl flex gap-1 z-20 shadow-neon-white backdrop-blur-xl">
              <button 
                onClick={() => setSourceType('url')}
                className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'url' ? 'bg-white text-slate-950 font-bold' : 'text-slate-400 hover:text-white'}`}
              >
                  <Link className="w-3.5 h-3.5" /> URL
              </button>
              <button 
                onClick={() => setSourceType('file')}
                className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'file' ? 'bg-orange-500 text-white font-bold' : 'text-slate-400 hover:text-white'}`}
              >
                  <Upload className="w-3.5 h-3.5" /> DOSYA
              </button>
              <button 
                onClick={() => setSourceType('text')}
                className={`px-4 md:px-6 py-2 rounded-lg text-[10px] md:text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'text' ? 'bg-white text-slate-950 font-bold' : 'text-slate-400 hover:text-white'}`}
              >
                  <AlignLeft className="w-3.5 h-3.5" /> METİN
              </button>
          </div>
      </div>

      {/* Input Section */}
      <div className="glass-panel rounded-3xl p-6 md:p-10 space-y-8 relative z-10 pt-16 bg-white/5 border-white/20 shadow-neon-white">
         <form onSubmit={handleGenerate} className="space-y-10">
            <div className="space-y-4">
                {sourceType === 'url' && (
                    <>
                        <label className="text-xs text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase">
                            <Link className="w-4 h-4 text-white" /> Kaynak URL
                        </label>
                        <div className="relative">
                            <input
                                type="url"
                                value={urlInput}
                                onChange={(e) => setUrlInput(e.target.value)}
                                placeholder="https://ornek.com/ilginc-makale"
                                className="w-full bg-slate-950/50 border border-white/20 rounded-2xl px-6 py-5 text-lg text-white placeholder:text-slate-700 focus:ring-2 focus:ring-white focus:border-white transition-all shadow-inner shadow-white/5"
                            />
                            <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-white/20">
                                <Sparkles className="w-5 h-5" />
                            </div>
                        </div>
                    </>
                )}

                {sourceType === 'file' && (
                    <>
                        <label className="text-xs text-orange-400 font-mono tracking-widest flex items-center gap-2 uppercase">
                            <Upload className="w-4 h-4" /> Kaynak Dosya
                        </label>
                        <div 
                            onClick={() => fileInputRef.current?.click()}
                            className={`group relative w-full border-2 border-dashed rounded-2xl p-10 transition-all cursor-pointer flex flex-col items-center justify-center gap-6 ${fileData ? 'border-orange-500/50 bg-orange-500/5' : 'border-white/20 hover:border-white hover:bg-white/5'}`}
                        >
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                onChange={handleFileChange} 
                                className="hidden" 
                                accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx"
                            />
                            {fileData ? (
                                <div className="flex flex-col items-center gap-4 animate-in zoom-in-95">
                                    <div className="relative">
                                        {fileData.mime.startsWith('image/') ? (
                                            <img src={`data:${fileData.mime};base64,${fileData.base64}`} alt="Önizleme" className="h-32 w-auto rounded-xl object-cover border border-orange-500/30 shadow-2xl" />
                                        ) : (
                                            <div className="h-32 w-32 bg-slate-900 rounded-xl border border-orange-500/30 flex items-center justify-center shadow-2xl">
                                                <FileType className="w-12 h-12 text-orange-500/50" />
                                            </div>
                                        )}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setFileData(null); }}
                                            className="absolute -top-3 -right-3 p-2 bg-red-500 hover:bg-red-600 rounded-full text-white shadow-xl transition-colors"
                                        >
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                    <div className="text-center">
                                        <p className="text-sm font-bold text-white font-mono max-w-[300px] truncate">{fileData.name}</p>
                                        <p className="text-[10px] text-slate-500 uppercase font-mono tracking-widest mt-1">
                                            {formatFileSize(fileData.size)} • TARANMAYA HAZIR
                                        </p>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <div className="w-20 h-20 rounded-2xl bg-white/5 border border-white/20 flex items-center justify-center group-hover:scale-110 group-hover:border-white transition-all duration-500 shadow-neon-white">
                                        <FileText className="w-10 h-10 text-slate-400 group-hover:text-white" />
                                    </div>
                                    <div className="text-center">
                                        <p className="text-white font-medium text-lg">Bir dosya seçin veya buraya sürükleyin</p>
                                        <p className="text-[10px] text-slate-500 font-mono mt-3 uppercase tracking-tighter">
                                            PDF, DOCX, PPTX, XLSX, RESİMLER (MAKS 15MB)
                                        </p>
                                    </div>
                                </>
                            )}
                        </div>
                    </>
                )}

                {sourceType === 'text' && (
                    <>
                        <label className="text-xs text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase">
                            <AlignLeft className="w-4 h-4 text-white" /> Metin Girişi
                        </label>
                        <div className="relative">
                            <textarea
                                value={textInput}
                                onChange={(e) => setTextInput(e.target.value)}
                                placeholder="Görselleştirmek istediğiniz metni buraya yapıştırın..."
                                className="w-full bg-slate-950/50 border border-white/20 rounded-2xl px-6 py-5 text-base text-white placeholder:text-slate-700 focus:ring-2 focus:ring-white focus:border-white transition-all shadow-inner shadow-white/5 h-48 md:h-64 resize-none font-sans"
                            />
                            <div className="absolute right-6 bottom-6 pointer-events-none text-white/10">
                                <FileText className="w-6 h-6" />
                            </div>
                        </div>
                    </>
                )}
            </div>

            {/* Layout, Style & Language Controls */}
            <div className="grid md:grid-cols-3 gap-8">
                {/* Format/Layout Selection */}
                <div className="space-y-4">
                     <label className="text-xs text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase">
                        <Monitor className="w-4 h-4 text-orange-400" /> Görsel Format
                    </label>
                    <div className="flex gap-2">
                        <button
                            type="button"
                            onClick={() => setAspectRatio("9:16")}
                            className={`flex-1 py-3 px-3 rounded-xl font-mono text-[11px] transition-all border flex items-center justify-center gap-2 ${
                                aspectRatio === "9:16" 
                                ? 'bg-orange-500 text-white border-orange-500 shadow-neon-orange font-bold' 
                                : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                            }`}
                        >
                            <Smartphone className="w-3.5 h-3.5" /> DİKEY
                        </button>
                        <button
                            type="button"
                            onClick={() => setAspectRatio("16:9")}
                            className={`flex-1 py-3 px-3 rounded-xl font-mono text-[11px] transition-all border flex items-center justify-center gap-2 ${
                                aspectRatio === "16:9" 
                                ? 'bg-orange-500 text-white border-orange-500 shadow-neon-orange font-bold' 
                                : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                            }`}
                        >
                            <Monitor className="w-3.5 h-3.5" /> YATAY
                        </button>
                    </div>
                    <p className="text-[9px] text-slate-500 font-mono uppercase text-center tracking-tighter">YÜKSEK ÇÖZÜNÜRLÜK (2K) AKTİF</p>
                </div>

                <div className="space-y-4">
                     <label className="text-xs text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase">
                        <Palette className="w-4 h-4 text-white" /> Sanatsal Stil
                    </label>
                    <div className="grid grid-cols-2 gap-2">
                        {SKETCH_STYLES.map(style => (
                            <button
                                key={style}
                                type="button"
                                onClick={() => setSelectedStyle(style)}
                                className={`py-3 px-3 rounded-xl font-mono text-[11px] transition-all border whitespace-nowrap truncate ${
                                    selectedStyle === style 
                                    ? 'bg-white text-slate-950 border-white font-bold shadow-neon-white' 
                                    : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                                }`}
                            >
                                {style}
                            </button>
                        ))}
                    </div>
                </div>

                 <div className="space-y-4">
                     <label className="text-xs text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase">
                        <Globe className="w-4 h-4 text-white" /> Çıktı Dili
                    </label>
                    <div className="relative">
                        <select
                            value={selectedLanguage}
                            onChange={(e) => setSelectedLanguage(e.target.value)}
                            className="w-full bg-slate-900/50 border border-white/20 rounded-xl px-4 py-4 text-sm text-white focus:ring-2 focus:ring-white focus:border-white font-mono appearance-none cursor-pointer hover:bg-white/10 transition-colors"
                        >
                             {LANGUAGES.map((lang) => (
                                <option key={lang.value} value={lang.value} className="bg-slate-900 text-slate-300">
                                    {lang.label}
                                </option>
                             ))}
                        </select>
                         <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                        </div>
                    </div>
                 </div>
            </div>

            <button
                type="submit"
                disabled={loading || (sourceType === 'url' && !urlInput.trim()) || (sourceType === 'file' && !fileData) || (sourceType === 'text' && !textInput.trim())}
                className="w-full py-6 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-2xl font-black transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-3 font-mono text-lg tracking-widest shadow-2xl"
            >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                {loading ? "İŞLENİYOR..." : "İNFOGRAFİK OLUŞTUR"}
            </button>
         </form>
      </div>

      {error && (
        <div className="glass-panel border-red-500/50 p-6 rounded-2xl flex items-center gap-4 text-red-400 animate-in fade-in font-mono text-sm bg-red-500/5">
          <AlertCircle className="w-6 h-6 flex-shrink-0 text-red-500" />
          <p>{error}</p>
        </div>
      )}

      {loading && (
        <LoadingState message={loadingStage || 'İÇERİK_OKUNUYOR'} type="article" />
      )}

      {/* Result Section */}
      {imageData && !loading && (
        <div className="glass-panel rounded-3xl p-2 animate-in fade-in slide-in-from-bottom-8 duration-1000 bg-white/5 border-white/20 shadow-2xl shadow-white/5">
            <div className="px-6 py-5 flex items-center justify-between border-b border-white/10 mb-2 bg-white/5 rounded-t-2xl">
                <h3 className="text-sm font-bold text-white flex items-center gap-2 font-mono uppercase tracking-widest">
                  <Sparkles className="w-4 h-4 text-orange-400" /> Oluşturulan_Sonuç
                </h3>
                <div className="flex items-center gap-3">
                    <button 
                        onClick={() => setFullScreenImage({src: `data:image/png;base64,${imageData}`, alt: "İnfografik"})}
                        className="p-2.5 hover:bg-white/10 rounded-xl text-slate-400 hover:text-white transition-all border border-transparent hover:border-white/20"
                        title="Tam Ekran"
                    >
                        <Maximize className="w-5 h-5" />
                    </button>
                    <a href={`data:image/png;base64,${imageData}`} download="site-taslagi.png" className="flex items-center gap-2 bg-white text-slate-950 hover:bg-orange-500 hover:text-white transition-all font-mono px-6 py-3 rounded-xl font-bold shadow-lg">
                        <Download className="w-5 h-5" /> PNG_İNDİR
                    </a>
                </div>
            </div>
            <div className={`rounded-2xl overflow-hidden bg-white relative mx-auto ${aspectRatio === "16:9" ? "max-w-4xl" : "max-w-xl"}`}>
                <img src={`data:image/png;base64,${imageData}`} alt="İnfografik" className="w-full h-auto object-contain max-h-[1200px] mx-auto" />
            </div>
        </div>
      )}
    </div>
  );
};

export default ArticleToInfographic;

