                                className="w-full bg-slate-950/50 border border-white/20 rounded-3xl px-10 py-8 text-2xl text-white placeholder:text-slate-700 focus:ring-4 focus:ring-white/10 focus:border-white transition-all shadow-inner shadow-white/5 outline-none"
                            />
                            <div className="absolute right-10 top-1/2 -translate-y-1/2 pointer-events-none text-white/20">
                                <Sparkles className="w-8 h-8" />
                            </div>
                        </div>
                    </>
                )}

                {sourceType === 'file' && (
                    <>
                        <label className="text-sm text-orange-400 font-mono tracking-[0.3em] flex items-center gap-3 uppercase font-black">
                            <Upload className="w-6 h-6" /> Kaynak Dosya
                        </label>
                        <div 
                            onClick={() => fileInputRef.current?.click()}
                            className={`group relative w-full border-4 border-dashed rounded-[40px] p-20 transition-all cursor-pointer flex flex-col items-center justify-center gap-10 ${fileData ? 'border-orange-500/50 bg-orange-500/5' : 'border-white/20 hover:border-white hover:bg-white/5'}`}
                        >
                            <input 
                                type="file" 
                                ref={fileInputRef} 
                                onChange={handleFileChange} 
                                className="hidden" 
                                accept="image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx"
                            />
                            {fileData ? (
                                <div className="flex flex-col items-center gap-8 animate-in zoom-in-95">
                                    <div className="relative">
                                        {fileData.mime.startsWith('image/') ? (
                                            <img src={`data:${fileData.mime};base64,${fileData.base64}`} alt="Önizleme" className="h-48 w-auto rounded-3xl object-cover border-2 border-orange-500/30 shadow-2xl" />
                                        ) : (
                                            <div className="h-48 w-48 bg-slate-900 rounded-3xl border-2 border-orange-500/30 flex items-center justify-center shadow-2xl">
                                                <FileType className="w-20 h-20 text-orange-500/50" />
                                            </div>
                                        )}
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); setFileData(null); }}
                                            className="absolute -top-6 -right-6 p-4 bg-red-500 hover:bg-red-600 rounded-full text-white shadow-2xl transition-all hover:scale-110"
                                        >
                                            <X className="w-6 h-6" />
                                        </button>
                                    </div>
                                    <div className="text-center">
                                        <p className="text-2xl font-black text-white font-mono max-w-[500px] truncate">{fileData.name}</p>
                                        <p className="text-xs text-slate-500 uppercase font-mono tracking-[0.2em] mt-3">
                                            {formatFileSize(fileData.size)} • TARANMAYA HAZIR
                                        </p>
                                    </div>
                                </div>
                            ) : (
                                <>
                                    <div className="w-32 h-32 rounded-[32px] bg-white/5 border-2 border-white/20 flex items-center justify-center group-hover:scale-110 group-hover:border-white transition-all duration-500 shadow-neon-white">
                                        <FileText className="w-16 h-16 text-slate-400 group-hover:text-white" />
                                    </div>
                                    <div className="text-center space-y-4">
                                        <p className="text-white font-black text-3xl">Bir dosya seçin veya buraya sürükleyin</p>
                                        <p className="text-xs text-slate-500 font-mono uppercase tracking-[0.2em]">
                                            PDF, DOCX, PPTX, XLSX, RESİMLER (MAKS 15MB)
                                        </p>
                                    </div>
                                </>
                            )}
                        </div>
                    </>
                )}

                {sourceType === 'text' && (
                    <>
                        <label className="text-sm text-white/50 font-mono tracking-[0.3em] flex items-center gap-3 uppercase font-black">
                            <AlignLeft className="w-6 h-6 text-white" /> Metin Girişi
                        </label>
                        <div className="relative">
                            <textarea
