                                onChange={(e) => setTextInput(e.target.value)}
                                placeholder="Görselleştirmek istediğiniz metni buraya yapıştırın..."
                                className="w-full bg-slate-950/50 border border-white/20 rounded-[40px] px-12 py-12 text-xl text-white placeholder:text-slate-700 focus:ring-4 focus:ring-white/10 focus:border-white transition-all shadow-inner shadow-white/5 h-80 md:h-[600px] resize-none font-sans outline-none leading-relaxed"
