                        <button
                            type="button"
                            onClick={() => setAspectRatio("16:9")}
                            className={`flex-1 py-5 px-4 rounded-2xl font-mono text-sm transition-all border-2 flex items-center justify-center gap-3 ${
                                aspectRatio === "16:9" 
                                ? 'bg-orange-500 text-white border-orange-500 shadow-neon-orange font-black' 
                                : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                            }`}
                        >
                            <Monitor className="w-5 h-5" /> YATAY
                        </button>
                    </div>
                    <p className="text-[11px] text-slate-500 font-mono uppercase text-center tracking-[0.2em] font-black">YÜKSEK ÇÖZÜNÜRLÜK (2K) AKTİF</p>
                </div>

                <div className="space-y-6">
                     <label className="text-xs text-white/50 font-mono tracking-[0.2em] flex items-center gap-3 uppercase font-black">
