                    <div className="grid grid-cols-2 gap-3">
                        {SKETCH_STYLES.map(style => (
                            <button
                                key={style}
                                type="button"
                                onClick={() => setSelectedStyle(style)}
                                className={`py-4 px-3 rounded-2xl font-mono text-xs transition-all border-2 whitespace-nowrap truncate ${
                                    selectedStyle === style 
                                    ? 'bg-white text-slate-950 border-white font-black shadow-neon-white' 
                                    : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                                }`}
                            >
                                {style}
                            </button>
                        ))}
                    </div>
                </div>

                 <div className="space-y-6">
                     <label className="text-xs text-white/50 font-mono tracking-[0.2em] flex items-center gap-3 uppercase font-black">
                        <Globe className="w-5 h-5 text-white" /> Çıktı Dili
                    </label>
                    <div className="relative">
                        <select
                            value={selectedLanguage}
                            onChange={(e) => setSelectedLanguage(e.target.value)}
                            className="w-full bg-slate-900/50 border-2 border-white/10 rounded-2xl px-6 py-5 text-base text-white focus:ring-4 focus:ring-white/10 focus:border-white font-mono appearance-none cursor-pointer hover:bg-white/10 transition-colors outline-none font-bold"
                        >
                             {LANGUAGES.map((lang) => (
                                <option key={lang.value} value={lang.value} className="bg-slate-900 text-slate-300">
                                    {lang.label}
                                </option>
                             ))}
                        </select>
                         <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500">
                            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
                        </div>
                    </div>
                 </div>
            </div>

            <button
                type="submit"
                disabled={loading || (sourceType === 'url' && !urlInput.trim()) || (sourceType === 'file' && !fileData) || (sourceType === 'text' && !textInput.trim())}
                className="w-full py-10 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-[32px] font-black transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-5 font-mono text-3xl tracking-[0.2em] shadow-2xl uppercase"
            >
                {loading ? <Loader2 className="w-10 h-10 animate-spin" /> : <Sparkles className="w-10 h-10" />}
                {loading ? "İŞLENİYOR..." : "İNFOGRAFİK OLUŞTUR"}
            </button>
         </form>
      </div>

      {error && (
        <div className="max-w-5xl mx-auto glass-panel border-red-500/50 p-10 rounded-3xl flex items-center gap-8 text-red-400 animate-in fade-in font-mono text-lg bg-red-500/5">
