      )}

      {loading && (
        <div className="scale-150 py-32">
            <LoadingState message={loadingStage || 'İÇERİK_OKUNUYOR'} type="article" />
        </div>
      )}

      {/* Result Section */}
      {imageData && !loading && (
        <div className="glass-panel rounded-[64px] p-6 animate-in fade-in slide-in-from-bottom-8 duration-1000 bg-white/5 border-white/20 shadow-2xl shadow-white/5">
            <div className="px-10 py-10 flex items-center justify-between border-b border-white/10 mb-6 bg-white/5 rounded-t-[58px]">
