                        title="Tam Ekran"
                    >
                        <Maximize className="w-8 h-8" />
                    </button>
                    <a href={`data:image/png;base64,${imageData}`} download="site-taslagi.png" className="flex items-center gap-4 bg-white text-slate-950 hover:bg-orange-500 hover:text-white transition-all font-mono px-12 py-6 rounded-3xl font-black text-xl shadow-2xl">
