import React, { useState, useRef } from 'react';
import { generateArticleInfographic, generateInfographicFromFile, generateInfographicFromText } from '../services/geminiService';
import { Citation, ArticleHistoryItem } from '../types';
import { Link, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, ExternalLink, BookOpen, Clock, Maximize, Upload, FileText, X, Calendar, FileType, AlignLeft, Monitor, Smartphone } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface ArticleToInfographicProps {
    history: ArticleHistoryItem[];
    onAddToHistory: (item: ArticleHistoryItem) => void;
}

const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Temiz Minimalist",
    "Koyu Mod Teknoloji",
    "Özel"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "German (Germany)", value: "German" },
  { label: "Spanish (Mexico)", value: "Spanish" },
  { label: "French (France)", value: "French" },
];

const ArticleToInfographic: React.FC<ArticleToInfographicProps> = ({ history, onAddToHistory }) => {
  const [sourceType, setSourceType] = useState<'url' | 'file' | 'text'>('url');
  const [urlInput, setUrlInput] = useState('');
  const [textInput, setTextInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("9:16");
  const [fileData, setFileData] = useState<{ base64: string; mime: string; name: string; size: number } | null>(null);
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const addToHistory = (source: string, image: string, cites: Citation[]) => {
      let title = source;
      if (sourceType === 'url') {
          try { title = new URL(source).hostname; } catch(e) {}
      } else if (sourceType === 'file') {
          title = fileData?.name || "Yüklenen Dosya";
      } else {
          title = textInput.substring(0, 20) + "...";
      }

      const newItem: ArticleHistoryItem = {
          id: Date.now().toString(),
          title: title,
          url: sourceType === 'url' ? source : sourceType === 'file' ? 'file-upload' : 'raw-text',
          imageData: image,
          citations: cites,
          date: new Date()
      };
      onAddToHistory(newItem);
  };

  const loadFromHistory = (item: ArticleHistoryItem) => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
      if (item.url === 'raw-text') {
          setSourceType('text');
      } else if (item.url === 'file-upload') {
          setSourceType('file');
      } else {
          setSourceType('url');
          setUrlInput(item.url);
      }
      setImageData(item.imageData);
      setCitations(item.citations);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          if (file.size > 15 * 1024 * 1024) {
              setError("Dosya boyutu 15MB limitini aşıyor.");
              return;
          }
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = (reader.result as string).split(',')[1];
              setFileData({ base64, mime: file.type, name: file.name, size: file.size });
              setError(null);
          };
          reader.readAsDataURL(file);
      }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (sourceType === 'url' && !urlInput.trim()) {
        setError("Lütfen geçerli bir URL girin.");
        return;
    }
    if (sourceType === 'file' && !fileData) {
        setError("Lütfen bir dosya yükleyin.");
        return;
    }
    if (sourceType === 'text' && !textInput.trim()) {
        setError("Lütfen metin girin.");
        return;
    }

    setLoading(true);
    setError(null);
    setImageData(null);
    setCitations([]);
    setLoadingStage('BAŞLATILIYOR...');

    try {
      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      let result;

      if (sourceType === 'url') {
          result = await generateArticleInfographic(urlInput, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      } else if (sourceType === 'file') {
          result = await generateInfographicFromFile(fileData!.base64, fileData!.mime, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      } else {
          result = await generateInfographicFromText(textInput, styleToUse, (stage) => {
              setLoadingStage(stage);
          }, selectedLanguage, aspectRatio);
      }

      if (result && result.imageData) {
          setImageData(result.imageData);
          setCitations(result.citations || []);
          addToHistory(sourceType === 'url' ? urlInput : sourceType === 'file' ? fileData!.name : textInput, result.imageData, result.citations || []);
      } else {
          throw new Error("İnfografik oluşturulamadı. Lütfen farklı bir stil deneyin.");
      }
    } catch (err: any) {
      setError(err.message || "Beklenmedik bir hata oluştu.");
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  const formatFileSize = (bytes: number) => {
      if (bytes === 0) return '0 Bayt';
      const k = 1024;
      const sizes = ['Bayt', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <div className="max-w-[1500px] mx-auto space-y-32 mb-48">

      {fullScreenImage && (
          <ImageViewer 
            src={fullScreenImage.src} 
            alt={fullScreenImage.alt} 
            onClose={() => setFullScreenImage(null)} 
          />
      )}

      {/* Hero Section */}
      <div className="text-center max-w-6xl mx-auto space-y-12">
        <h2 className="text-8xl md:text-[10rem] font-black tracking-tighter text-white font-sans leading-[0.8]">
          Site<span className="text-orange-500">Taslağı</span>.
        </h2>
        <p className="text-slate-400 text-3xl md:text-5xl font-extralight tracking-tight max-w-5xl mx-auto leading-tight">
          Saniyeler içinde 2K ultra netlikte profesyonel infografik posterler üretin.
        </p>
      </div>

      {/* Source Selector Tabs */}
      <div className="flex justify-center -mb-12">
          <div className="bg-white/5 border-2 border-white/20 p-3 rounded-[2.5rem] flex gap-3 z-20 shadow-neon-white backdrop-blur-3xl">
              <button 
                onClick={() => setSourceType('url')}
                className={`px-10 md:px-16 py-6 rounded-3xl text-lg md:text-2xl font-mono transition-all flex items-center gap-4 ${sourceType === 'url' ? 'bg-white text-slate-950 font-black shadow-xl' : 'text-slate-400 hover:text-white'}`}
              >
                  <Link className="w-7 h-7" /> URL
              </button>
              <button 
                onClick={() => setSourceType('file')}
                className={`px-10 md:px-16 py-6 rounded-3xl text-lg md:text-2xl font-mono transition-all flex items-center gap-4 ${sourceType === 'file' ? 'bg-orange-500 text-white font-black shadow-neon-orange' : 'text-slate-400 hover:text-white'}`}
              >
                  <Upload className="w-7 h-7" /> DOSYA
              </button>
              <button 
                onClick={() => setSourceType('text')}
                className={`px-10 md:px-16 py-6 rounded-3xl text-lg md:text-2xl font-mono transition-all flex items-center gap-4 ${sourceType === 'text' ? 'bg-white text-slate-950 font-black shadow-xl' : 'text-slate-400 hover:text-white'}`}
              >
                  <AlignLeft className="w-7 h-7" /> METİN
              </button>
          </div>
      </div>

      {/* Input Section */}
      <div className="glass-panel rounded-[5rem] p-12 md:p-24 space-y-24 relative z-10 pt-32 bg-white/5 border-2 border-white/20 shadow-neon-white">
         <form onSubmit={handleGenerate} className="space-y-24">
            <div className="space-y-12">
                {sourceType === 'url' && (
                    <>
                        <label className="text-lg text-white/50 font-mono tracking-[0.4em] flex items-center gap-5 uppercase font-black">
