                        </div>
                    </div>
                 </div>
            </div>

            <button
                type="submit"
                disabled={loading || (sourceType === 'url' && !urlInput.trim()) || (sourceType === 'file' && !fileData) || (sourceType === 'text' && !textInput.trim())}
                className="w-full py-12 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-[3.5rem] font-black transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-8 font-mono text-4xl tracking-[0.3em] shadow-[0_40px_100px_rgba(0,0,0,0.5)] uppercase active:scale-[0.98]"
