import React, { useState } from 'react';
import { fetchRepoFileTree } from '../services/githubService';
import { generateInfographic } from '../services/geminiService';
import { RepoFileTree, ViewMode, RepoHistoryItem } from '../types';
import { AlertCircle, Loader2, Layers, Box, Download, Sparkles, Command, Palette, Globe, Clock, Maximize, KeyRound, Smartphone, Monitor } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface RepoAnalyzerProps {
  onNavigate: (mode: ViewMode, data?: any) => void;
  history: RepoHistoryItem[];
  onAddToHistory: (item: RepoHistoryItem) => void;
}

const FLOW_STYLES = [
    "Modern Veri Akışı",
    "El Çizimi Blueprint",
    "Kurumsal Beyaz",
    "Neon Siberpunk",
    "Özel"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "Deutsch (Germany)", value: "German" },
];

const RepoAnalyzer: React.FC<RepoAnalyzerProps> = ({ onNavigate, history, onAddToHistory }) => {
  const [repoInput, setRepoInput] = useState('');
  const [selectedStyle, setSelectedStyle] = useState(FLOW_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("16:9");
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState<string>('');

  const [infographicData, setInfographicData] = useState<string | null>(null);
  const [infographic3DData, setInfographic3DData] = useState<string | null>(null);
  const [generating3D, setGenerating3D] = useState(false);
  const [currentFileTree, setCurrentFileTree] = useState<RepoFileTree[] | null>(null);
  const [currentRepoName, setCurrentRepoName] = useState<string>('');

  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const parseRepoInput = (input: string): { owner: string, repo: string } | null => {
    const cleanInput = input.trim().replace(/\/$/, '');
    try {
      const url = new URL(cleanInput);
      if (url.hostname === 'github.com') {
        const parts = url.pathname.split('/').filter(Boolean);
        if (parts.length >= 2) return { owner: parts[0], repo: parts[1] };
      }
    } catch (e) { }
    const parts = cleanInput.split('/');
    if (parts.length === 2 && parts[0] && parts[1]) return { owner: parts[0], repo: parts[1] };
    return null;
  };

  const addToHistory = (repoName: string, imageData: string, is3D: boolean, style: string) => {
     const newItem: RepoHistoryItem = {
         id: Date.now().toString(),
         repoName,
         imageData,
         is3D,
         style,
         date: new Date()
     };
     onAddToHistory(newItem);
  };

  const handleApiError = (err: any) => {
      if (err.message && err.message.includes("Requested entity was not found")) {
          const confirmSwitch = window.confirm(
              "ÖDEME GEREKLİ: Mevcut API anahtarı bu modelleri kullanma yetkisine sahip değil.\n\n" +
              "Bu özellik ücretli bir Google Cloud projesi gerektirir."
          );
          if (confirmSwitch) {
              window.location.reload();
          }
      }
      setError(err.message || 'Analiz sırasında beklenmedik bir hata oluştu.');
  }

  const handleAnalyze = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setInfographicData(null);
    setInfographic3DData(null);
    setCurrentFileTree(null);

    const repoDetails = parseRepoInput(repoInput);
    if (!repoDetails) {
      setError('Geçersiz format. "kullanici/depo" kullanın.');
      return;
    }

    setLoading(true);
    setCurrentRepoName(repoDetails.repo);
    try {
      setLoadingStage('GITHUB\'A BAĞLANILIYOR');
      const fileTree = await fetchRepoFileTree(repoDetails.owner, repoDetails.repo);

      if (fileTree.length === 0) throw new Error('Bu depoda ilgili kod dosyası bulunamadı.');
      setCurrentFileTree(fileTree);

      setLoadingStage('YAPI ANALİZ EDİLİYOR VE OLUŞTURULUYOR');

      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      const infographicBase64 = await generateInfographic(repoDetails.repo, fileTree, styleToUse, false, selectedLanguage, aspectRatio);

      if (infographicBase64) {
        setInfographicData(infographicBase64);
        addToHistory(repoDetails.repo, infographicBase64, false, styleToUse);
      } else {
          throw new Error("Görsel oluşturulamadı.");
      }

    } catch (err: any) {
      handleApiError(err);
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  const handleGenerate3D = async () => {
    if (!currentFileTree || !currentRepoName) return;
    setGenerating3D(true);
    try {
      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      const data = await generateInfographic(currentRepoName, currentFileTree, styleToUse, true, selectedLanguage, "16:9");
      if (data) {
          setInfographic3DData(data);
          addToHistory(currentRepoName, data, true, styleToUse);
      }
    } catch (err: any) {
      handleApiError(err);
    } finally {
      setGenerating3D(false);
    }
  };

  return (
    <div className="max-w-[1700px] mx-auto space-y-32 mb-48">

      {fullScreenImage && (
          <ImageViewer 
            src={fullScreenImage.src} 
            alt={fullScreenImage.alt} 
            onClose={() => setFullScreenImage(null)} 
          />
      )}

      {/* Hero Section */}
      <div className="text-center max-w-6xl mx-auto space-y-12">
        <h2 className="text-8xl md:text-[11rem] font-black tracking-tighter text-white font-sans leading-[0.8]">
          Depo <span className="text-orange-500">Mimarisi</span>.
        </h2>
        <p className="text-slate-400 text-3xl md:text-5xl font-extralight tracking-tight max-w-5xl mx-auto leading-tight">
          GitHub depolarını 2K çözünürlükte mimari planlara ve 3D modellere dönüştürün.
        </p>
      </div>

      {/* Input Section */}
      <div className="max-w-7xl mx-auto relative z-10">
        <form onSubmit={handleAnalyze} className="glass-panel rounded-[5rem] p-8 md:p-12 bg-white/5 border-2 border-white/20 transition-all focus-within:ring-8 focus-within:ring-white/5 focus-within:border-white shadow-[0_50px_150px_rgba(0,0,0,0.6)]">
          <div className="flex items-center p-6">
             <div className="pl-8 text-white/50">
                <Command className="w-14 h-14" />
             </div>
             <input
                type="text"
                value={repoInput}
                onChange={(e) => setRepoInput(e.target.value)}
                placeholder="kullanici/depo_ismi"
                className="w-full bg-transparent border-none text-white placeholder:text-slate-700 focus:ring-0 text-5xl px-12 py-8 font-mono outline-none font-black"
              />
              <div className="pr-6">
                <button
                type="submit"
                disabled={loading || !repoInput.trim()}
                className="px-16 py-8 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-[3rem] font-black transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-6 font-mono text-3xl tracking-[0.1em] uppercase shadow-2xl active:scale-95"
                >
                {loading ? <Loader2 className="w-10 h-10 animate-spin" /> : "ANALİZ_ET"}
                </button>
             </div>
          </div>

          <div className="mt-12 pt-16 border-t border-white/10 px-12 pb-10 grid md:grid-cols-2 gap-24">
             <div className="space-y-10">
                 <div className="flex items-center gap-6 text-white/40 font-mono text-xl uppercase tracking-[0.4em] font-black">
                     <Palette className="w-8 h-8" /> Görsel Stil
                 </div>
                 <div className="flex flex-wrap gap-5">
                     {FLOW_STYLES.map(style => (
                         <button
                            key={style}
                            type="button"
                            onClick={() => setSelectedStyle(style)}
                            className={`text-lg px-8 py-5 rounded-[2rem] font-mono transition-all border-2 ${
                                selectedStyle === style 
                                ? 'bg-white text-slate-950 border-white font-black shadow-neon-white scale-105' 
                                : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30 hover:text-white'
                            }`}
                         >
                             {style}
                         </button>
                     ))}
                 </div>
             </div>

             <div className="space-y-10">
                 <div className="flex items-center gap-6 text-orange-400 font-mono text-xl uppercase tracking-[0.4em] font-black">
                     <Monitor className="w-8 h-8" /> Format & Çıktı Dili
                 </div>
                 <div className="flex gap-6">
                    <button
                        type="button"
                        onClick={() => setAspectRatio("9:16")}
                        className={`flex-1 py-6 px-10 rounded-[2rem] font-mono text-xl transition-all border-2 flex items-center justify-center gap-5 ${
                            aspectRatio === "9:16" 
                            ? 'bg-orange-500 text-white border-orange-500 font-black shadow-neon-orange scale-105' 
                            : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30'
                        }`}
                    >
                        <Smartphone className="w-8 h-8" /> DİKEY
                    </button>
                    <button
                        type="button"
                        onClick={() => setAspectRatio("16:9")}
                        className={`flex-1 py-6 px-10 rounded-[2rem] font-mono text-xl transition-all border-2 flex items-center justify-center gap-5 ${
                            aspectRatio === "16:9" 
                            ? 'bg-orange-500 text-white border-orange-500 font-black shadow-neon-orange scale-105' 
                            : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30'
                        }`}
                    >
                        <Monitor className="w-8 h-8" /> YATAY
                    </button>
                 </div>
                 <div className="flex items-center gap-6 bg-slate-900 border-2 border-white/10 rounded-[2.5rem] px-10 py-6">
                    <Globe className="w-8 h-8 text-white/40 shrink-0" />
                    <select
                        value={selectedLanguage}
                        onChange={(e) => setSelectedLanguage(e.target.value)}
                        className="bg-transparent border-none text-2xl text-white focus:ring-0 p-0 font-mono cursor-pointer flex-1 font-black outline-none"
                    >
                        {LANGUAGES.map((lang) => (
                        <option key={lang.value} value={lang.value} className="bg-slate-900 text-slate-300">
                            {lang.label}
                        </option>
                        ))}
                    </select>
                 </div>
             </div>
          </div>
        </form>
      </div>

      {loading && (
        <div className="scale-[1.8] py-64">
            <LoadingState message={loadingStage} type="repo" />
        </div>
      )}

      {infographicData && !loading && (
        <div className="animate-in fade-in slide-in-from-bottom-8 duration-1000">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
              <div className="glass-panel rounded-[5rem] p-6 bg-white/5 border-2 border-white/20 shadow-[0_50px_100px_rgba(0,0,0,0.4)]">
                 <div className="px-12 py-10 flex items-center justify-between border-b border-white/10 mb-8 gap-8">
                    <h3 className="text-3xl font-black text-white flex items-center gap-6 font-mono uppercase tracking-[0.2em]">
                      <Layers className="w-10 h-10 text-white" /> Akış Diyagramı (2K)
                    </h3>
                    <div className="flex items-center gap-6">
                      <button 
                        onClick={() => setFullScreenImage({src: `data:image/png;base64,${infographicData}`, alt: `${currentRepoName} 2D`})}
                        className="p-5 hover:bg-white/10 rounded-[2rem] text-slate-400 hover:text-white transition-all border-2 border-transparent hover:border-white/20"
                      >
                        <Maximize className="w-10 h-10" />
                      </button>
                      <a href={`data:image/png;base64,${infographicData}`} download={`${currentRepoName}-2d.png`} className="bg-white text-slate-950 hover:bg-white/80 transition-all font-mono px-12 py-6 rounded-[2rem] text-2xl font-black shadow-2xl flex items-center gap-6 uppercase active:scale-95">
                        <Download className="w-8 h-8" /> İNDİR
                      </a>
                    </div>
                </div>
                <div className={`rounded-[4rem] overflow-hidden bg-white relative border-2 border-white/10 mx-auto shadow-2xl ${aspectRatio === "16:9" ? "max-w-[1700px]" : "max-w-[900px]"}`}>
                    <img src={`data:image/png;base64,${infographicData}`} alt="Diyagram" className="w-full h-auto object-cover relative z-10 transition-transform hover:scale-[1.03] duration-1000" />
                </div>
              </div>

              <div className="glass-panel rounded-[5rem] p-6 bg-white/5 border-2 border-white/20 shadow-[0_50px_100px_rgba(0,0,0,0.4)] flex flex-col">
                 <div className="px-12 py-10 flex items-center justify-between border-b border-white/10 mb-8 shrink-0 gap-8">
                    <h3 className="text-3xl font-black text-white flex items-center gap-6 font-mono uppercase tracking-[0.2em]">
                      <Box className="w-10 h-10 text-orange-500" /> Holografik Model (3D)
                    </h3>
                </div>

                <div className="flex-1 rounded-[4rem] overflow-hidden bg-slate-950/50 relative flex items-center justify-center min-h-[700px] shadow-inner">
                  {infographic3DData ? (
                      <div className="w-full h-full flex items-center justify-center p-8">
                         <img src={`data:image/png;base64,${infographic3DData}`} alt="3D Model" className="w-full h-full object-contain rounded-[3rem] animate-in fade-in shadow-[0_40px_100px_rgba(245,158,11,0.1)]" />
                      </div>
                  ) : generating3D ? (
                    <div className="flex flex-col items-center justify-center gap-16 p-24 text-center animate-in fade-in">
                         <Loader2 className="w-28 h-28 animate-spin text-orange-500" />
                         <p className="text-orange-400 font-mono text-3xl animate-pulse tracking-[0.4em] uppercase font-black">HOLOGRAFİK MODEL OLUŞTURULUYOR...</p>
                    </div>
                  ) : (
                    <div className="flex flex-col items-center justify-center gap-16 p-24 text-center">
                        <div className="w-56 h-56 bg-orange-500/10 rounded-[5rem] flex items-center justify-center border-4 border-orange-500/20 shadow-neon-orange transition-transform hover:scale-110 duration-700">
                            <Box className="w-28 h-28 text-orange-500" />
                        </div>
                        <button 
                          onClick={handleGenerate3D}
                          className="px-20 py-10 bg-orange-500 text-white hover:bg-orange-600 rounded-[3.5rem] font-black transition-all flex items-center gap-8 font-mono text-3xl shadow-[0_30px_70px_rgba(245,158,11,0.4)] uppercase tracking-[0.1em] active:scale-95"
                        >
                          <Sparkles className="w-10 h-10" />
                          3D MODEL OLUŞTUR
                        </button>
                    </div>
                  )}
                </div>
              </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default RepoAnalyzer;

