import React, { useState, useRef } from 'react';
import { generateArticleInfographic, generateInfographicFromFile, generateInfographicFromText } from '../services/geminiService';
import { Citation, ArticleHistoryItem } from '../types';
import { Link, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, ExternalLink, BookOpen, Clock, Maximize, Upload, FileText, X, Calendar, FileType, AlignLeft, Monitor, Smartphone } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

interface ArticleToInfographicProps {
    history: ArticleHistoryItem[];
    onAddToHistory: (item: ArticleHistoryItem) => void;
}

const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Temiz Minimalist",
    "Koyu Mod Teknoloji",
    "Özel"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" },
  { label: "German (Germany)", value: "German" },
  { label: "Spanish (Mexico)", value: "Spanish" },
  { label: "French (France)", value: "French" },
];

const ArticleToInfographic: React.FC<ArticleToInfographicProps> = ({ history, onAddToHistory }) => {
  const [sourceType, setSourceType] = useState<'url' | 'file' | 'text'>('url');
  const [urlInput, setUrlInput] = useState('');
  const [textInput, setTextInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("9:16");
  const [fileData, setFileData] = useState<{ base64: string; mime: string; name: string; size: number } | null>(null);
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [customStyle, setCustomStyle] = useState('');
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [downloadName, setDownloadName] = useState('infografik');
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  const sanitizeFilename = (name: string) => {
      return name.toLowerCase()
          .replace(/[ğĞ]/g, 'g')
          .replace(/[üÜ]/g, 'u')
          .replace(/[şŞ]/g, 's')
          .replace(/[ıİ]/g, 'i')
          .replace(/[öÖ]/g, 'o')
          .replace(/[çÇ]/g, 'c')
          .replace(/[^a-z0-9]/gi, '-')
          .replace(/-+/g, '-')
          .substring(0, 50);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          if (file.size > 15 * 1024 * 1024) {
              setError("Dosya boyutu 15MB limitini aşıyor.");
              return;
          }
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = (reader.result as string).split(',')[1];
              setFileData({ base64, mime: file.type, name: file.name, size: file.size });
              setError(null);
          };
          reader.readAsDataURL(file);
      }
  };

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (sourceType === 'url' && !urlInput.trim()) return;
    if (sourceType === 'file' && !fileData) return;
    if (sourceType === 'text' && !textInput.trim()) return;

    setLoading(true);
    setError(null);
    setImageData(null);
    setCitations([]);
    setLoadingStage('BAŞLATILIYOR...');

    // Determine download name
    let name = 'infografik';
    if (sourceType === 'url') {
        try { name = new URL(urlInput).hostname; } catch(e) { name = 'web-sayfasi'; }
    } else if (sourceType === 'file') {
        name = fileData?.name.split('.')[0] || 'dosya';
    } else {
        name = textInput.substring(0, 20);
    }
    setDownloadName(sanitizeFilename(name));

    try {
      const styleToUse = selectedStyle === 'Özel' ? customStyle : selectedStyle;
      let result;

      if (sourceType === 'url') {
          result = await generateArticleInfographic(urlInput, styleToUse, (stage) => setLoadingStage(stage), selectedLanguage, aspectRatio);
      } else if (sourceType === 'file') {
          result = await generateInfographicFromFile(fileData!.base64, fileData!.mime, styleToUse, (stage) => setLoadingStage(stage), selectedLanguage, aspectRatio);
      } else {
          result = await generateInfographicFromText(textInput, styleToUse, (stage) => setLoadingStage(stage), selectedLanguage, aspectRatio);
      }

      if (result && result.imageData) {
          setImageData(result.imageData);
          setCitations(result.citations || []);
      } else {
          throw new Error("İnfografik oluşturulamadı.");
      }
    } catch (err: any) {
      setError(err.message || "Beklenmedik bir hata oluştu.");
    } finally {
      setLoading(false);
      setLoadingStage('');
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-12 mb-24">

      {fullScreenImage && (
          <ImageViewer src={fullScreenImage.src} alt={fullScreenImage.alt} onClose={() => setFullScreenImage(null)} />
      )}

      {/* Hero Section */}
      <div className="text-center space-y-6">
        <h2 className="text-5xl md:text-6xl font-black tracking-tight text-white">
          Site<span className="text-orange-500">Taslağı</span>.
        </h2>
        <p className="text-slate-400 text-lg md:text-xl font-light">
          Mobil uyumlu, 2K yüksek çözünürlüklü infografikler oluşturun.
        </p>
      </div>

      {/* Source Selector Tabs */}
      <div className="flex justify-center -mb-6">
          <div className="bg-white/5 border border-white/20 p-1.5 rounded-2xl flex gap-1 z-20 shadow-neon-white backdrop-blur-3xl">
              <button 
                onClick={() => setSourceType('url')}
                className={`px-6 py-2.5 rounded-xl text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'url' ? 'bg-white text-slate-950 font-black' : 'text-slate-400 hover:text-white'}`}
              >
                  <Link className="w-4 h-4" /> URL
              </button>
              <button 
                onClick={() => setSourceType('file')}
                className={`px-6 py-2.5 rounded-xl text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'file' ? 'bg-orange-500 text-white font-black' : 'text-slate-400 hover:text-white'}`}
              >
                  <Upload className="w-4 h-4" /> DOSYA
              </button>
              <button 
                onClick={() => setSourceType('text')}
                className={`px-6 py-2.5 rounded-xl text-xs font-mono transition-all flex items-center gap-2 ${sourceType === 'text' ? 'bg-white text-slate-950 font-black' : 'text-slate-400 hover:text-white'}`}
              >
                  <AlignLeft className="w-4 h-4" /> METİN
              </button>
          </div>
      </div>

      {/* Input Section */}
      <div className="glass-panel rounded-3xl p-6 md:p-10 space-y-8 relative z-10 pt-16 bg-white/5 border border-white/20 shadow-neon-white">
         <form onSubmit={handleGenerate} className="space-y-8">
            <div className="space-y-4">
                {sourceType === 'url' && (
                    <div className="relative">
                        <input
                            type="url"
                            value={urlInput}
                            onChange={(e) => setUrlInput(e.target.value)}
                            placeholder="Makale URL'sini buraya yapıştırın"
                            className="w-full bg-slate-950/50 border border-white/10 rounded-2xl px-6 py-4 text-lg text-white placeholder:text-slate-700 focus:ring-2 focus:ring-white transition-all outline-none"
                        />
                    </div>
                )}

                {sourceType === 'file' && (
                    <div 
                        onClick={() => fileInputRef.current?.click()}
                        className={`group relative w-full border-2 border-dashed rounded-3xl p-8 transition-all cursor-pointer flex flex-col items-center justify-center gap-4 ${fileData ? 'border-orange-500/50 bg-orange-500/5' : 'border-white/10 hover:border-white/30'}`}
                    >
                        <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*,.pdf,.doc,.docx,.ppt,.pptx" />
                        {fileData ? (
                            <div className="text-center font-mono text-xs">
                                <p className="text-white font-bold">{fileData.name}</p>
                                <p className="text-slate-500 mt-1 uppercase">Yüklemeye Hazır</p>
                            </div>
                        ) : (
                            <div className="text-center">
                                <Upload className="w-10 h-10 text-slate-500 mx-auto mb-3" />
                                <p className="text-sm text-slate-400">Dosya seçin veya sürükleyin (PDF, DOCX, Resim)</p>
                            </div>
                        )}
                    </div>
                )}

                {sourceType === 'text' && (
                    <textarea
                        value={textInput}
                        onChange={(e) => setTextInput(e.target.value)}
                        placeholder="İçeriği buraya yapıştırın..."
                        className="w-full bg-slate-950/50 border border-white/10 rounded-2xl px-6 py-6 text-base text-white placeholder:text-slate-700 focus:ring-2 focus:ring-white transition-all h-64 md:h-80 resize-none outline-none"
                    />
                )}
            </div>

            {/* Controls */}
            <div className="grid md:grid-cols-3 gap-6">
                <div className="space-y-3">
                     <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black">
                        <Monitor className="w-4 h-4 text-orange-400" /> Format
                    </label>
                    <div className="flex gap-2">
                        <button type="button" onClick={() => setAspectRatio("9:16")} className={`flex-1 py-3 px-2 rounded-xl text-[11px] font-mono border-2 transition-all ${aspectRatio === "9:16" ? 'bg-orange-500 text-white border-orange-500 shadow-neon-orange font-black' : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30'}`}>
                            <Smartphone className="w-4 h-4 mx-auto mb-1" /> DİKEY
                        </button>
                        <button type="button" onClick={() => setAspectRatio("16:9")} className={`flex-1 py-3 px-2 rounded-xl text-[11px] font-mono border-2 transition-all ${aspectRatio === "16:9" ? 'bg-orange-500 text-white border-orange-500 shadow-neon-orange font-black' : 'bg-white/5 text-slate-400 border-white/10 hover:border-white/30'}`}>
                            <Monitor className="w-4 h-4 mx-auto mb-1" /> YATAY
                        </button>
                    </div>
                </div>

                <div className="space-y-3">
                     <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black">
                        <Palette className="w-4 h-4 text-white" /> Stil
                    </label>
                    <select value={selectedStyle} onChange={(e) => setSelectedStyle(e.target.value)} className="w-full bg-slate-900 border-2 border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:ring-2 focus:ring-white outline-none">
                        {SKETCH_STYLES.map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>

                 <div className="space-y-3">
                     <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black">
                        <Globe className="w-4 h-4 text-white" /> Dil
                    </label>
                    <select value={selectedLanguage} onChange={(e) => setSelectedLanguage(e.target.value)} className="w-full bg-slate-900 border-2 border-white/10 rounded-xl px-4 py-3 text-sm text-white focus:ring-2 focus:ring-white outline-none">
                        {LANGUAGES.map(l => <option key={l.value} value={l.value}>{l.label}</option>)}
                    </select>
                 </div>
            </div>

            <button
                type="submit"
                disabled={loading}
                className="w-full py-5 bg-white text-slate-950 hover:bg-orange-500 hover:text-white rounded-2xl font-black transition-all disabled:opacity-50 flex items-center justify-center gap-3 font-mono text-lg tracking-widest uppercase shadow-2xl"
            >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                {loading ? "İŞLENİYOR..." : "İNFOGRAFİK OLUŞTUR"}
            </button>
         </form>
      </div>

      {error && (
        <div className="glass-panel border-red-500/50 p-6 rounded-2xl flex items-center gap-4 text-red-400 font-mono text-sm bg-red-500/5 shadow-xl">
          <AlertCircle className="w-5 h-5 flex-shrink-0 text-red-500" />
          <p>{error}</p>
        </div>
      )}

      {loading && <LoadingState message={loadingStage} type="article" />}

      {/* Result Section - Responsive Image Display */}
