import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

export async function generateInfographic(
  repoName: string, 
  fileTree: RepoFileTree[], 
  style: string, 
  is3D: boolean = false,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "16:9"
): Promise<string | null> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 150).map(f => f.path).join(', ');

  let styleGuidelines = "";
  let dimensionPrompt = "";

  if (is3D) {
      styleGuidelines = `VISUAL STYLE: High-end 3D Cinematic Render. The architecture should look like a glowing, holographic physical model. Use ray-tracing effects and depth of field.`;
      dimensionPrompt = `PERSPECTIVE: Isometric 3D view. 2K resolution.`;
  } else {
      switch (style) {
          case "El Çizimi Blueprint":
              styleGuidelines = `STYLE: Architectural Technical Drawing. Navy blue background, white chalk-like precise lines. High contrast.`;
              break;
          case "Kurumsal Beyaz":
              styleGuidelines = `STYLE: Premium Business Minimalist. Crisp Swiss-style typography. High-end grid layout.`;
              break;
          case "Neon Siberpunk":
              styleGuidelines = `STYLE: Cyberpunk UI/UX. Deep black background, vivid glowing neon aesthetics.`;
              break;
          case "Modern Veri Akışı":
              styleGuidelines = `STYLE: Flat Vector Infographic. Clean shapes, professional color palettes.`;
              break;
          default:
              styleGuidelines = `STYLE: Professional Digital Poster Design. High hierarchy.`;
              break;
      }
      dimensionPrompt = aspectRatio === "9:16" ? "LAYOUT: Vertical mobile-first flow." : "LAYOUT: Wide landscape view.";
  }

  const prompt = `Create a professional 2K technical infographic for: "${repoName}".
  ${styleGuidelines}
  ${dimensionPrompt}
  - TEXT RULES: Use BOLD, SHARP, and HIGH-CONTRAST typography. Labels must be perfectly legible on smartphone screens.
  - CONTENT: Map the logical data flow of this codebase: ${limitedTree}
  - LANGUAGE: All text in ${language}.
  - QUALITY: Ultra-HD, 2K resolution, sharp edges.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        responseModalities: [Modality.IMAGE],
        imageConfig: { aspectRatio, imageSize: "2K" }
      },
    });
    const parts = response.candidates?.[0]?.content?.parts;
    return parts?.find(p => p.inlineData)?.inlineData?.data || null;
  } catch (error) {
    return handleApiError(error);
  }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SİTE ANALİZ EDİLİYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        const analysisPrompt = `Analyze the website deeply: ${url}. 
        Identify if it's a Brand/Corporate landing page or an Article.
        Extract: 1. Main Value Proposition 2. Core Services/Products 3. Brand Identity 4. Social Proof/Stats.
        Structure this content for a HIGH-QUALITY infographic. Language: ${language}.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        structuralSummary = `Summary of ${url} for an infographic. Language: ${language}.`;
    }

    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, citations };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("METİN İŞLENİYOR...");

    const analysisPrompt = `Condense this text into a visual content plan for a professional infographic: "${text}". Language: ${language}.`;
    const analysisResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: analysisPrompt
    });

    return await finalizeInfographic(analysisResponse.text || "", style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("DOSYA ANALİZ EDİLİYOR...");

    const analysisResponse = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [
                { inlineData: { data: fileBase64, mimeType } },
                { text: `Extract key infographic structure from this file. Language: ${language}.` }
            ]
        }
    });

    return await finalizeInfographic(analysisResponse.text || "", style, onProgress, language, aspectRatio);
}

async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("TASARIM OLUŞTURULUYOR...");

    const imagePrompt = `Create a high-end 2K professional infographic poster.
    LAYOUT: ${aspectRatio === "9:16" ? "Long vertical flow for mobile" : "Wide landscape poster"}.
    STYLE: ${style}. 
    CONTENT PLAN: ${summary}
    TYPOGRAPHY RULES:
    - MAXIMUM LEGIBILITY: Text must be sharp and scaled for small screens.
    - HIGH HIERARCHY: Bold titles, clear icons, bullet points.
    - VISUAL STORYTELLING: Use meaningful icons and balanced whitespace.
    - LANGUAGE: ${language}.
    - QUALITY: 2K Ultra-HD, Sharp rendering, No blurry elements.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function askNodeSpecificQuestion(
  nodeLabel: string, 
  question: string, 
  fileTree: RepoFileTree[]
): Promise<string> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 300).map(f => f.path).join('\n');
  const prompt = `Architect Context: ${limitedTree}\nComponent: ${nodeLabel}\nQuestion: ${question}`;
  const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: { parts: [{ text: prompt }] }
  });
  return response.text || "Cevap üretilemedi.";
}

export async function editImageWithGemini(base64Data: string, mimeType: string, prompt: string): Promise<string | null> {
  const ai = getAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Data, mimeType } },
        { text: prompt }
      ]
    },
    config: { responseModalities: [Modality.IMAGE], imageConfig: { imageSize: "2K" } }
  });
  const parts = response.candidates?.[0]?.content?.parts;
  return parts?.find(p => p.inlineData)?.inlineData?.data || null;
}

