import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO İÇERİĞİ ANALİZ EDİLİYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        const analysisPrompt = `Deeply analyze this YouTube video: ${youtubeUrl}.
        Identify the main topic, key timestamps/sections, and primary takeaways.
        Target Language: ${language}.
        Structure the analysis as a "Visual Summary Plan" for a professional infographic.
        Extract any specific statistics, quotes, or key names mentioned in the video context.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        structuralSummary = `YouTube Video Summary for ${youtubeUrl}. Language: ${language}.`;
    }

    return await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
}

// ... existing generateInfographic functions ...

async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("TASARIM OLUŞTURULUYOR...");

    const imagePrompt = `Create a MASTER-GRADE 2K professional infographic poster.
    LAYOUT: ${aspectRatio === "9:16" ? "Vertical storytelling flow (mobile-first)" : "Cinematic landscape poster"}.
    STYLE: ${style}. 
    CONTENT PLAN: ${summary}
    TYPOGRAPHY CORE RULES:
    - MAXIMUM LEGIBILITY: Use bold, high-contrast, premium fonts.
    - MOBILE SCALE: All text must be perfectly readable on small screens without zooming.
    - VISUAL HIERARCHY: Use distinct headers, subheaders, and icon-based bullet points.
    - NEGATIVE SPACE: Maintain professional balance, no clutter.
    - LANGUAGE: All text in image MUST be ${language}.
    - QUALITY: 2K Resolution, ultra-sharp rendering, studio quality.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

