/**
 * Analiz Edilmiş İçeriği Görsele Dönüştürme (Final Aşaması)
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("TASARIM MOTORU ÇALIŞTIRILIYOR...");

    const imagePrompt = `Yüksek kaliteli (2K) profesyonel bir infografik poster oluştur.
    DÜZEN: ${aspectRatio === "9:16" ? "Uzun dikey akış (mobil odaklı)" : "Geniş sinematik poster"}.
    STİL: ${style}. 
    İÇERİK PLANI (BU VERİLERİ KULLAN): ${summary}
    TASARIM KURALLARI:
    - BİLGİ YOĞUNLUĞU: Poster boş kalmamalı, analizdeki tüm ana noktaları görselleştir.
    - OKUNABİLİRLİK: Metinler keskin, fontlar modern ve yüksek kontrastlı olmalı.
    - HİYERARŞİ: Başlıklar büyük, alt bilgiler daha küçük ama net olmalı.
    - DİL: Görseldeki TÜM metinler ${language} dilinde olmalı.
    - KALİTE: 2K Çözünürlük, ultra keskin hatlar, profesyonel renk paleti.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

