const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Koyu Mod Teknoloji",
    "Sinematik Analiz"
];

const LANGUAGES = [
