import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Gelişmiş Doğrulama ve Derinlik
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO KAYNAĞI DOĞRULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];
    let videoTitle = "";

    try {
        // Modelden önce linkteki videoyu kesin olarak bulmasını ve içeriğini analiz etmesini istiyoruz.
        const analysisPrompt = `KESİN TALİMAT: Verilen bu YouTube linkindeki videoyu analiz et: ${youtubeUrl}.

        ADIM 1: Videonun adını ve kanal adını tam olarak belirle. Yanlış videoyu analiz etme.
        ADIM 2: Videonun içeriğini (transkript, açıklama, ana bölümler) detaylıca incele.
        ADIM 3: Analiz sonucunu şu başlıklarla Türkçe (${language}) olarak raporla:
        - VİDEO KİMLİĞİ: [Video Adı - Kanal]
        - ÖZET: Videonun ana fikri nedir?
        - ANAHTAR BÖLÜMLER: Saniye saniye veya konu konu en önemli kısımlar.
        - ÖNEMLİ BİLGİLER: Videoda geçen rakamlar, isimler, tavsiyeler.
        - TASARIM FİKRİ: Bu içeriği temsil eden 3 ana sembol.

        Google Search aracını kullanarak bu videonun gerçek içeriğine ulaştığından emin ol.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });

        structuralSummary = analysisResponse.text || "";

        // Alıntıları topla
        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        structuralSummary = `Video içeriği analiz edilemedi ancak görsel tasarım denenecek. Link: ${youtubeUrl}`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İÇERİK TASARIMA DÖNÜŞTÜRÜLÜYOR...");

    const imagePrompt = `PROFESYONEL İNFOGRAFİK TASARIMI (2K).
    İÇERİK ANALİZİ: ${summary}
    STİL: ${style}. 
    DÜZEN: ${aspectRatio === "9:16" ? "Mobil için uzun dikey tasarım" : "Geniş yatay poster"}.
    GÖRSEL KURALLAR:
    - OKUNABİLİRLİK: Metinler telefon ekranında bile net okunacak büyüklükte olmalı. Keskin fontlar kullan.
    - BİLGİ DOYGUNLUĞU: Analizde geçen tüm önemli noktaları ve rakamları posterin içine estetik bir hiyerarşiyle yerleştir.
    - DİL: Poster üzerindeki tüm metinler %100 ${language} olmalı.
    - KALİTE: Ultra-sharp, 2K çözünürlük, profesyonel renk uyumu.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

