/**
 * YouTube İçerik Analizi - Gelişmiş Doğrulama ve Derinlik
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO KAYNAĞI DOĞRULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        // Modelden önce linkteki videoyu kesin olarak bulmasını ve içeriğini analiz etmesini istiyoruz.
        // URL'i temizleyip göndersek de model bazen popüler videoları karıştırabilir.
        const analysisPrompt = `KRİTİK GÖREV: Aşağıdaki spesifik YouTube URL'indeki videoyu analiz et: ${youtubeUrl}

        KESİN KURAL: Başka bir videoyu veya benzer başlıklı sonuçları analiz etme. Sadece bu URL'deki videonun içeriğine odaklan. Yanlış videoyu (örneğin popüler çocuk videoları gibi alakasız içerikleri) analiz edersen görev başarısız sayılır.

        ADIM 1: Google Search aracını kullanarak bu URL'in (${youtubeUrl}) güncel başlığını ve kanal ismini bul.
        ADIM 2: Videonun içeriğini (açıklama, varsa transkript veya özetler) detaylıca incele.
        ADIM 3: Analiz sonucunu şu başlıklarla ${language} dilinde raporla:
        - ANALİZ EDİLEN VİDEO: [Videonun Tam Adı]
        - KANAL: [Kanal Adı]
        - İÇERİK ÖZETİ: Videoda ne anlatılıyor?
        - ANA BÖLÜMLER: Videodaki en önemli kısımlar.
        - ÖNEMLİ VERİLER: Videoda geçen tüm rakamlar, isimler, tarihler veya spesifik terimler.
        - TASARIM DÜZENİ: Bu bilgileri bir infografikte nasıl hiyerarşik olarak yerleştireceğinin planı.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });

        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        console.warn("Analysis stage failed, falling back to simple prompt:", e);
        structuralSummary = `Video içeriği derinlemesine analiz edilemedi. URL: ${youtubeUrl}. Genel bir özet tasarımı hazırlanıyor.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İÇERİK TASARIMA DÖNÜŞTÜRÜLÜYOR...");

    const imagePrompt = `PROFESYONEL İNFOGRAFİK TASARIMI (2K).
    İÇERİK ANALİZ VERİLERİ (GÖRSELDEKİ TÜM BİLGİLER BURADAN ALINMALI): ${summary}
    STİL: ${style}. 
    DÜZEN: ${aspectRatio === "9:16" ? "Uzun dikey infografik akışı" : "Yatay geniş teknik poster"}.
    GÖRSEL KURALLAR:
    - KESİN OKUNABİLİRLİK: Metinler telefon ekranında bile net okunacak büyüklükte, kalın ve yüksek kontrastlı olmalı.
    - VERİ YOĞUNLUĞU: Analizdeki tüm önemli bilgileri, rakamları ve başlıkları posterin içine estetik bir hiyerarşiyle yerleştir.
    - DİL: Poster üzerindeki TÜM metinler ${language} dilinde olmalı.
    - KALİTE: Ultra-sharp, 2K çözünürlük, profesyonel grafik tasarım standartları.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

