import React, { useState, useMemo, useEffect } from 'react';
import { generateYoutubeInfographic } from '../services/geminiService';
import { Citation } from '../types';
import { Youtube, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, Maximize, Smartphone, Monitor, BookOpen, ExternalLink, FileSearch, CheckCircle2, RefreshCw } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Koyu Mod Teknoloji",
    "Sinematik Analiz"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" }
];

const YoutubeToInfographic: React.FC = () => {
  const [urlInput, setUrlInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("9:16");
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [analysisText, setAnalysisText] = useState<string | null>(null);
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  useEffect(() => {
    if (error) setError(null);
  }, [urlInput]);

  // En Sağlam YouTube ID Tespiti (Short, Long, Share, Embed linkleri için)
  const videoId = useMemo(() => {
    if (!urlInput) return null;

    const regExp = /^.*(youtu\.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = urlInput.match(regExp);

    if (match && match[2].length === 11) {
        return match[2];
    }

    // URL API ile ek kontrol
    try {
        const url = new URL(urlInput);
        if (url.hostname === 'youtu.be') return url.pathname.slice(1).split('?')[0];
        if (url.hostname.includes('youtube.com')) {
            const v = url.searchParams.get('v');
            if (v) return v;
            const pathParts = url.pathname.split('/');
            return pathParts[pathParts.length - 1];
        }
    } catch (e) {}

    return null;
  }, [urlInput]);

  // Grounding için temiz URL
  const cleanUrl = useMemo(() => {
    if (!videoId) return urlInput;
    return `https://www.youtube.com/watch?v=${videoId}`;
  }, [videoId, urlInput]);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoId) {
        setError("Lütfen geçerli bir YouTube video linki girin.");
        return;
    }

    setLoading(true);
    setError(null);
    setImageData(null);
    setAnalysisText(null);

    try {
      console.log("Generating infographic for:", cleanUrl);
      const result = await generateYoutubeInfographic(cleanUrl, selectedStyle, (s) => setLoadingStage(s), selectedLanguage, aspectRatio);

      if (result && result.imageData) {
          setImageData(result.imageData);
          setAnalysisText(result.analysisText || null);
          setCitations(result.citations || []);
      } else {
          throw new Error("Görsel oluşturulamadı. Lütfen API anahtarınızın yüklü ve bakiyenizin olduğundan emin olun.");
      }
    } catch (err: any) {
      console.error("Generator failed:", err);
      setError(err.message || "Bir hata oluştu. Lütfen linki kontrol edip tekrar deneyin.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-12 mb-24">
      {fullScreenImage && <ImageViewer src={fullScreenImage.src} alt={fullScreenImage.alt} onClose={() => setFullScreenImage(null)} />}

      <div className="text-center space-y-8 py-4">
        <h2 className="text-6xl md:text-8xl font-black tracking-tight text-white leading-tight">
          Video<span className="text-red-500">Analiz</span>.
        </h2>
        <p className="text-slate-400 text-xl md:text-2xl font-light max-w-4xl mx-auto leading-relaxed">
          YouTube videolarını <span className="text-white font-bold italic">içerik analiziyle</span> profesyonel infografiklere dönüştürün.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative z-10">
        <div className="glass-panel rounded-[3rem] p-8 md:p-12 space-y-8 bg-white/5 border border-white/20 shadow-neon-white h-fit">
            <form onSubmit={handleGenerate} className="space-y-8">
                <div className="relative">
                    <div className="absolute left-6 top-1/2 -translate-y-1/2 text-red-500">
                        <Youtube className="w-8 h-8" />
                    </div>
                    <input 
                        type="url" 
                        value={urlInput} 
