import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Kapsamlı Grounding ve Tasarım Protokolü
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO KAYNAĞI TARAFIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        // Modelin içeriği (çocuk videosu, eğlence vb.) reddetmeden analiz etmesi için akademik/teknik bir prompt.
        const analysisPrompt = `GÖREV: Aşağıdaki YouTube bağlantısındaki videoyu bir eğitim ve içerik uzmanı gözüyle analiz et: ${youtubeUrl}

        KAPSAM:
        1. Videonun içeriği ne olursa olsun (çocuk şarkısı, teknik eğitim, vlog vb.), bu içeriği görsel bir özete dönüştürmek için parçalarına ayır.
        2. Google Search aracını kullanarak bu URL'in (${youtubeUrl}) güncel başlığını, kanalını ve ana hatlarını kesin olarak doğrula.
        3. Analizi şu yapıda ${language} olarak sun:
           - BAŞLIK: [Videonun Tam Adı]
           - ÖZET: İçeriğin temel amacı ve mesajı.
           - ANA BÖLÜMLER: Videodaki sahneler, konular veya bölümler.
           - ÖNEMLİ VERİLER: Karakterler, nesneler, rakamlar veya anahtar kelimeler.
           - TASARIM ÖNERİSİ: İnfografik için hiyerarşik yerleşim planı.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });

        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        console.warn("Deep analysis failed, using fallback processing:", e);
        structuralSummary = `Video içeriği: ${youtubeUrl}. Bu içerik için modern bir görsel özet hazırlanıyor.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR (2K)...");

    const imagePrompt = `PROFESYONEL İNFOGRAFİK POSTER (2K ÇÖZÜNÜRLÜK).
    İÇERİK ANALİZ VERİLERİ: ${summary}
    STİL: ${style}. 
    DÜZEN: ${aspectRatio === "9:16" ? "Dikey (Mobil Okuma Formatı)" : "Yatay (Geniş Ekran Formatı)"}.

    TASARIM KURALLARI:
    - OKUNABİLİRLİK: Metinler poster üzerinde net, büyük ve yüksek kontrastlı olmalı.
    - DİL: Poster üzerindeki TÜM metinler, başlıklar ve etiketler istisnasız ${language} dilinde olmalıdır.
    - HİYERARŞİ: Analizdeki ana fikirleri ve sayısal verileri görselin içine estetik bir düzende yerleştir.
    - KALİTE: Ultra-keskin çizgiler, profesyonel renk paleti, modern tipografi.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA ANALİZ EDİLİYOR...");
    let structuralSummary = "";
    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `Bu linkteki içeriği analiz et ve infografik planı çıkar: ${url}. Dil: ${language}.`,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği. Dil: ${language}.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    return await finalizeInfographic(text, style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [{ inlineData: { data: fileBase64, mimeType } }, { text: "Dosya içeriğini analiz et." }]
        }
    });
    return await finalizeInfographic(response.text || "", style, onProgress, language, aspectRatio);
}

export async function generateInfographic(
  repoName: string, 
  fileTree: RepoFileTree[], 
  style: string, 
  is3D: boolean = false,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "16:9"
): Promise<string | null> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 150).map(f => f.path).join(', ');
  const prompt = `Teknik Mimari Diyagram: ${repoName}. Dosyalar: ${limitedTree}. Stil: ${style}. Dil: ${language}. 2K Sharp Typography.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        responseModalities: [Modality.IMAGE],
        imageConfig: { aspectRatio, imageSize: "2K" }
      },
    });
    const parts = response.candidates?.[0]?.content?.parts;
    return parts?.find(p => p.inlineData)?.inlineData?.data || null;
  } catch (error) {
    return handleApiError(error);
  }
}

export async function editImageWithGemini(base64Data: string, mimeType: string, prompt: string): Promise<string | null> {
  const ai = getAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Data, mimeType } },
        { text: prompt }
      ]
    },
    config: { responseModalities: [Modality.IMAGE], imageConfig: { imageSize: "2K" } }
  });
  const parts = response.candidates?.[0]?.content?.parts;
  return parts?.find(p => p.inlineData)?.inlineData?.data || null;
}

export async function askNodeSpecificQuestion(
  nodeLabel: string, 
  question: string, 
  fileTree: RepoFileTree[]
): Promise<string> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 300).map(f => f.path).join('\n');
  const prompt = `Architect: ${limitedTree}\nComponent: ${nodeLabel}\nQuestion: ${question}`;
  const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: { parts: [{ text: prompt }] }
  });
  return response.text || "Cevap üretilemedi.";
}

