    if (!urlInput) return null;

    // Temizleme: whitespace'leri temizle
    const cleanUrl = urlInput.trim();

    // 1. Standart watch?v= formatı
    if (cleanUrl.includes('v=')) {
        const parts = cleanUrl.split('v=')[1];
        return parts.split('&')[0].split('?')[0].substring(0, 11);
    }

    // 2. Short/Share youtu.be formatı
    if (cleanUrl.includes('youtu.be/')) {
        const parts = cleanUrl.split('youtu.be/')[1];
        return parts.split('&')[0].split('?')[0].substring(0, 11);
    }

    // 3. Embed formatı
    if (cleanUrl.includes('embed/')) {
        const parts = cleanUrl.split('embed/')[1];
        return parts.split('&')[0].split('?')[0].substring(0, 11);
    }

    // 4. Shorts formatı
    if (cleanUrl.includes('shorts/')) {
        const parts = cleanUrl.split('shorts/')[1];
        return parts.split('&')[0].split('?')[0].substring(0, 11);
    }

    return null;
  }, [urlInput]);

  // Grounding için temiz ve tam URL
