      console.error("Youtube to Infographic Error:", err);
      setError(err.message || "Analiz sırasında bir hata oluştu. Linkin herkese açık olduğundan emin olun.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-12 mb-24">
