import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Link Odaklı Derin Grounding Protokolü
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO İÇERİĞİNE ERİŞİLİYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        // AI'ya linki bir web sitesi gibi ziyaret etmesini ve içeriği "kazımasını" (crawl) söylüyoruz.
        const analysisPrompt = `KRİTİK GÖREV: Aşağıdaki spesifik YouTube sayfasını bir araştırma uzmanı gibi analiz et: ${youtubeUrl}

        KESİN TALİMATLAR:
        1. Google Search aracını kullanarak doğrudan bu URL'i (${youtubeUrl}) incele.
        2. Sadece başlığa bakma; videonun transkriptini, açıklamasını ve sunulan ana fikirleri tespit et.
        3. İçerik bir çocuk videosu, eğitim videosu veya karmaşık bir teknik konu olsa bile, içeriği reddetme ve profesyonel bir rapor oluştur.
        4. Analizi şu başlıklarla ${language} dilinde hazırla:
           - VİDEO KİMLİĞİ: [Resmi Başlık]
           - İÇERİK ÖZETİ: Videonun sunduğu temel bilgi ve akış.
           - ÖNEMLİ NOKTALAR: Videodan çıkarılan en kritik 5-7 veri/bilgi.
           - TASARIM ŞEMASI: Bu verilerin dikey bir infografikte nasıl görselleşeceği.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.2
            }
        });

        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        console.warn("Deep Grounding failed, using structural analysis fallback:", e);
        structuralSummary = `Video Sayfası: ${youtubeUrl}. İçerik görselleştirme hattına aktarılıyor.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK POSTER OLUŞTURULUYOR (2K)...");

    const imagePrompt = `PROFESYONEL İNFOGRAFİK POSTER (2K).
    İÇERİK VERİLERİ: ${summary}
    STİL: ${style}. 
    DÜZEN: ${aspectRatio === "9:16" ? "Uzun Dikey Format" : "Geniş Yatay Format"}.

    TASARIM STANDARTLARI:
    - OKUNABİLİRLİK: Metinler poster üzerinde net, yüksek kontrastlı ve büyük punto olmalı.
    - DİL: Poster üzerindeki TÜM metinler ve başlıklar ${language} dilinde olmalıdır.
    - DETAY: Analizdeki sayısal verileri ve ana başlıkları görselin içine estetik bir düzende yedir.
    - KALİTE: Ultra-sharp, profesyonel grafik tasarım, keskin detaylar.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
