import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Web Scraping ve Grounding Protokolü
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO SAYFASI ANALİZ EDİLİYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    try {
        // AI'ya linki bir web sitesi gibi ziyaret etmesini ve içeriği "kazımasını" söylüyoruz.
        // YouTube linkini doğrudan bir bilgi kaynağı olarak işlemesi için prompt güncellendi.
        const analysisPrompt = `KESİN TALİMAT: Aşağıdaki YouTube linkine Google Search aracını kullanarak git ve içeriğini oku: ${youtubeUrl}

        GÖREV:
        1. Bu linkteki (${youtubeUrl}) videonun başlığını, açıklamasını ve özellikle mevcutsa transkript/altyazı verilerini analiz et.
        2. Başka videolara gitme, sadece bu linkteki içeriğe odaklan.
        3. Videonun ana konusunu, anlatılan önemli bilgileri ve varsa sayısal verileri çıkar.
        4. Elde ettiğin bilgileri profesyonel bir infografik tasarımı için hiyerarşik bir yapıda ${language} dilinde özetle.

        Analizi şu başlıklarla sun:
        - VİDEO BAŞLIĞI: [Başlık]
        - ÖZET: [Kısa özet]
        - ÖNEMLİ MADDELER: [En az 5 önemli bilgi noktası]
        - TASARIM DÜZENİ: [Görsel yerleşim planı]`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.1 // Daha spesifik ve doğru analiz için düşük sıcaklık
            }
        });

        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
    } catch (e) {
        console.warn("YouTube Analysis failed:", e);
        structuralSummary = `Video Sayfası (${youtubeUrl}) için genel bir görselleştirme planı oluşturuluyor.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR (2K)...");

    const imagePrompt = `PROFESYONEL İNFOGRAFİK TASARIMI (2K ÇÖZÜNÜRLÜK).
    İÇERİK VERİLERİ: ${summary}
    STİL: ${style}. 
    DÜZEN: ${aspectRatio === "9:16" ? "Dikey (Mobil Okuma)" : "Yatay (Sinematik)"}.
    GÖRSEL KURALLAR:
    - Poster üzerindeki TÜM metinler ${language} dilinde olmalıdır.
    - Bilgiler çok net, okunaklı ve estetik bir tipografi ile yerleştirilmelidir.
    - Analizdeki başlıkları ve ana fikirleri görselin içine profesyonelce dağıt.
    - Modern, yüksek kontrastlı ve keskin grafikler kullan.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

