import React, { useState, useMemo, useEffect } from 'react';
import { generateYoutubeInfographic } from '../services/geminiService';
import { Citation } from '../types';
import { Youtube, Loader2, Download, Sparkles, AlertCircle, Palette, Globe, Maximize, Smartphone, Monitor, BookOpen, ExternalLink, FileSearch, CheckCircle2, RefreshCw, Code } from 'lucide-react';
import { LoadingState } from './LoadingState';
import ImageViewer from './ImageViewer';

const SKETCH_STYLES = [
    "Modern Editoryal",
    "Minimalist Beyaz",
    "Eğlenceli ve Canlı",
    "Koyu Mod Teknoloji",
    "Sinematik Analiz"
];

const LANGUAGES = [
  { label: "Türkçe (Türkiye)", value: "Turkish" },
  { label: "English (US)", value: "English" }
];

const YoutubeToInfographic: React.FC = () => {
  const [urlInput, setUrlInput] = useState('');
  const [aspectRatio, setAspectRatio] = useState<"16:9" | "9:16">("9:16");
  const [selectedStyle, setSelectedStyle] = useState(SKETCH_STYLES[0]);
  const [selectedLanguage, setSelectedLanguage] = useState(LANGUAGES[0].value);
  const [loading, setLoading] = useState(false);
  const [imageData, setImageData] = useState<string | null>(null);
  const [analysisText, setAnalysisText] = useState<string | null>(null);
  const [citations, setCitations] = useState<Citation[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStage, setLoadingStage] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  useEffect(() => {
    if (error) setError(null);
  }, [urlInput]);

  // Robust YouTube ID Tespiti (Iframe, si= parametreleri, shorts vb.)
  const videoId = useMemo(() => {
    if (!urlInput) return null;

    const input = urlInput.trim();

    // 1. Iframe içinden src çekme
    const iframeSrcMatch = input.match(/src=["']([^"']+)["']/i);
    const targetUrl = iframeSrcMatch ? iframeSrcMatch[1] : input;

    // 2. YouTube ID Regex (Standard, Shorts, Embed, youtu.be)
    const regex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?|shorts)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/\s]{11})/i;
    const match = targetUrl.match(regex);

    if (match && match[1]) {
        return match[1];
    }

    return null;
  }, [urlInput]);

  // AI Analizi için her zaman en temiz ve tam URL'i gönder
  const cleanUrl = useMemo(() => {
    if (!videoId) return urlInput;
    return `https://www.youtube.com/watch?v=${videoId}`;
  }, [videoId, urlInput]);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoId) {
        setError("Geçerli bir YouTube linki veya embed kodu bulunamadı.");
        return;
    }

    setLoading(true);
    setError(null);
    setImageData(null);
    setAnalysisText(null);

    try {
      console.log("Analyzing video:", cleanUrl);
      const result = await generateYoutubeInfographic(cleanUrl, selectedStyle, (s) => setLoadingStage(s), selectedLanguage, aspectRatio);

      if (result && result.imageData) {
          setImageData(result.imageData);
          setAnalysisText(result.analysisText || null);
          setCitations(result.citations || []);
      } else {
          throw new Error("Görsel oluşturma motoru yanıt vermedi.");
      }
    } catch (err: any) {
      console.error("Youtube Analysis Error:", err);
      setError(err.message || "Analiz sırasında bir hata oluştu.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-12 mb-24">
      {fullScreenImage && <ImageViewer src={fullScreenImage.src} alt={fullScreenImage.alt} onClose={() => setFullScreenImage(null)} />}

      <div className="text-center space-y-8 py-4">
        <h2 className="text-6xl md:text-8xl font-black tracking-tight text-white leading-tight">
          Video<span className="text-red-500">Analiz</span>.
        </h2>
        <p className="text-slate-400 text-xl md:text-2xl font-light max-w-4xl mx-auto leading-relaxed">
          Embed kodundan veya linkten <span className="text-white font-bold italic">otomatik analiz</span> ile infografik oluşturun.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 relative z-10">
        <div className="glass-panel rounded-[3rem] p-8 md:p-12 space-y-8 bg-white/5 border border-white/20 shadow-neon-white h-fit">
            <form onSubmit={handleGenerate} className="space-y-8">
                <div className="relative">
                    <div className="absolute left-6 top-1/2 -translate-y-1/2 text-red-500">
                        {urlInput.includes('<iframe') ? <Code className="w-8 h-8" /> : <Youtube className="w-8 h-8" />}
                    </div>
                    <input 
                        type="text" 
                        value={urlInput} 
                        onChange={(e) => setUrlInput(e.target.value)} 
                        placeholder="Video linkini veya embed kodunu yapıştırın..." 
                        className="w-full bg-slate-950/50 border border-white/10 rounded-3xl px-16 py-6 text-xl text-white placeholder:text-slate-700 focus:ring-4 focus:ring-red-500/20 outline-none font-bold" 
                    />
                </div>

                <div className="aspect-video w-full rounded-3xl overflow-hidden bg-black border border-white/10 shadow-2xl relative group">
                    {videoId ? (
                        <iframe
                            className="w-full h-full"
                            src={`https://www.youtube.com/embed/${videoId}?rel=0`}
                            title="YouTube video player"
                            frameBorder="0"
                            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                            allowFullScreen
                        ></iframe>
                    ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center text-slate-700 space-y-4">
                            <Youtube className="w-16 h-16 opacity-20" />
                            <p className="text-xs font-mono uppercase tracking-widest text-center px-6 italic">Lütfen bir kaynak girin...</p>
                        </div>
                    )}
                    {videoId && (
                         <div className="absolute top-4 right-4 bg-emerald-500 text-white px-3 py-1 rounded-full text-[10px] font-bold flex items-center gap-2 shadow-lg">
                            <CheckCircle2 className="w-3 h-3" /> KAYNAK TANIMLANDI
                         </div>
                    )}
                </div>

                <div className="grid grid-cols-2 gap-6">
                    <div className="space-y-3">
                        <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black"><Palette className="w-3 h-3" /> Stil</label>
                        <select value={selectedStyle} onChange={(e) => setSelectedStyle(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm text-white outline-none">
                            {SKETCH_STYLES.map(s => <option key={s} value={s}>{s}</option>)}
                        </select>
                    </div>
                    <div className="space-y-3">
                        <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black"><Globe className="w-3 h-3" /> Dil</label>
                        <select value={selectedLanguage} onChange={(e) => setSelectedLanguage(e.target.value)} className="w-full bg-slate-900 border border-white/10 rounded-xl px-4 py-3 text-sm text-white outline-none">
                            {LANGUAGES.map(l => <option key={l.value} value={l.value}>{l.label}</option>)}
                        </select>
                    </div>
                </div>

                <div className="space-y-3">
                    <label className="text-[10px] text-white/50 font-mono tracking-widest flex items-center gap-2 uppercase font-black"><Monitor className="w-3 h-3" /> Format</label>
                    <div className="flex gap-4">
                        <button type="button" onClick={() => setAspectRatio("9:16")} className={`flex-1 py-3 rounded-xl text-[10px] font-mono border transition-all ${aspectRatio === "9:16" ? 'bg-red-600 text-white border-red-600 shadow-lg' : 'bg-white/5 text-slate-400 border-white/10'}`}><Smartphone className="w-4 h-4 mx-auto mb-1" /> MOBİL</button>
                        <button type="button" onClick={() => setAspectRatio("16:9")} className={`flex-1 py-3 rounded-xl text-[10px] font-mono border transition-all ${aspectRatio === "16:9" ? 'bg-red-600 text-white border-red-600 shadow-lg' : 'bg-white/5 text-slate-400 border-white/10'}`}><Monitor className="w-4 h-4 mx-auto mb-1" /> YATAY</button>
                    </div>
                </div>

                <button type="submit" disabled={loading || !videoId} className="w-full py-6 bg-red-600 text-white hover:bg-red-700 rounded-[1.5rem] font-black transition-all disabled:opacity-50 flex items-center justify-center gap-4 font-mono text-lg tracking-widest uppercase shadow-xl">
                    {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <Sparkles className="w-6 h-6" />}
                    {loading ? "VİDEO ANALİZ EDİLİYOR..." : "VİDEOYU İŞLE"}
