import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Deep Grounding & Verification Protokolü
 * Yanlış video veya demo içerik sorununu çözmek için 'site:' operatörü kullanılır.
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO VERİLERİ SORGULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    // URL'den ID'yi temizle
    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("INVALID_URL_FORMAT");
    }

    try {
        // Prompt güncellendi: Daha geniş arama stratejisi
        const analysisPrompt = `GÖREV: Aşağıdaki YouTube Video ID'sine sahip içeriği bul ve analiz et.

        HEDEF VIDEO ID: ${videoId}
        LINK: ${youtubeUrl}

        ARAŞTIRMA ADIMLARI:
        1. Google Search aracını kullanarak şu terimleri ara: "${youtubeUrl}", "${videoId} youtube", "${videoId} video summary".
        2. Arama sonuçlarından videonun başlığını, kanalını ve açıklamasını doğrula.
        3. EĞER BU ID İLE EŞLEŞEN BİR VİDEO BULAMAZSAN, ÇIKTI OLARAK SADECE "ANALYSIS_FAILED_NO_DATA" YAZ.
        4. Video çocuklara özel olsa veya embed kapalı olsa bile, arama sonuçlarındaki metin verilerini (description, snippets) birleştirerek bir özet çıkar.

        ÇIKTI FORMATI (${language}):
        - DOĞRULANMIŞ BAŞLIK: [Arama sonucundan bulunan gerçek başlık]
        - KANAL: [Yayıncı Kanal]
        - İÇERİK ÖZETİ: Videonun gerçek konusu.
        - ÖNEMLİ NOKTALAR: 7 adet kritik bilgi maddesi.
        - GÖRSEL PLAN: Verilerin infografik yerleşimi.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.2, // Arama esnekliği için hafifçe artırıldı
            }
        });

        structuralSummary = analysisResponse.text || "";

        // Hata kontrolü: Model veri bulamadıysa
        if (structuralSummary.includes("ANALYSIS_FAILED_NO_DATA")) {
            throw new Error("VIDEO_NOT_FOUND_IN_SEARCH");
        }

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Doğrulanmış Kaynak" });
                }
            });
        }

        // Eğer sonuç çok kısaysa
        if (structuralSummary.length < 30) {
             // Fallback: Belki model özet yazdı ama kısa.
             if (structuralSummary.length < 5) throw new Error("INSUFFICIENT_DATA");
        }

    } catch (e: any) {
        console.warn("YouTube Deep Analysis error:", e.message);

        // Bilinen hataları fırlat
        if (e.message === "VIDEO_NOT_FOUND_IN_SEARCH" || e.message === "INSUFFICIENT_DATA" || e.message === "INVALID_URL_FORMAT") {
            throw e; 
        }

        // Genel API hataları veya bilinmeyen durumlar için fallback
        // Ancak search hatası değilse (örn. API overload), kullanıcıya bildirmek daha iyi.
        // Fallback message only if we don't have explicit failure
         structuralSummary = `Video ID: ${videoId}. Analiz verisi tam olarak çekilemedi ancak görselleştirme şablonu oluşturuluyor.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 * Gemini 3 Pro Image modeli kullanılarak 2K çözünürlükte infografik üretilir.
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR (GEMINI 3 PRO)...");

    const imagePrompt = `Create a PROFESSIONAL INFOGRAPHIC POSTER (2K Resolution).
    DATA SOURCE: ${summary}
    VISUAL STYLE: ${style}. 
    LAYOUT: ${aspectRatio === "9:16" ? "Vertical (Mobile First)" : "Horizontal (Cinematic)"}.

    STRICT DESIGN RULES:
    - ALL TEXT MUST BE IN ${language}.
    - Use Large, Bold, High-Contrast Typography.
    - Organize the "Critical Data Points" from the source into a structured visual hierarchy.
    - Do not use generic placeholder text; use the actual info from the summary.
    - Clean, modern, vector-style aesthetics.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview', // En yüksek kalite model
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA ANALİZ EDİLİYOR...");
    let structuralSummary = "";
    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: `Bu linkteki içeriği analiz et ve infografik planı çıkar: ${url}. Dil: ${language}.`,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği. Dil: ${language}.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    return await finalizeInfographic(text, style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [{ inlineData: { data: fileBase64, mimeType } }, { text: "Dosya içeriğini analiz et." }]
        }
    });
    return await finalizeInfographic(response.text || "", style, onProgress, language, aspectRatio);
}

export async function generateInfographic(
  repoName: string, 
  fileTree: RepoFileTree[], 
  style: string, 
  is3D: boolean = false,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "16:9"
): Promise<string | null> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 150).map(f => f.path).join(', ');
  const prompt = `Teknik Mimari Diyagram: ${repoName}. Dosyalar: ${limitedTree}. Stil: ${style}. Dil: ${language}. 2K Sharp Typography.`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        responseModalities: [Modality.IMAGE],
        imageConfig: { aspectRatio, imageSize: "2K" }
      },
    });
    const parts = response.candidates?.[0]?.content?.parts;
    return parts?.find(p => p.inlineData)?.inlineData?.data || null;
  } catch (error) {
    return handleApiError(error);
  }
}

export async function editImageWithGemini(base64Data: string, mimeType: string, prompt: string): Promise<string | null> {
  const ai = getAiClient();
  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: {
      parts: [
        { inlineData: { data: base64Data, mimeType } },
        { text: prompt }
      ]
    },
    config: { responseModalities: [Modality.IMAGE], imageConfig: { imageSize: "2K" } }
  });
  const parts = response.candidates?.[0]?.content?.parts;
  return parts?.find(p => p.inlineData)?.inlineData?.data || null;
}

export async function askNodeSpecificQuestion(
  nodeLabel: string, 
  question: string, 
  fileTree: RepoFileTree[]
): Promise<string> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 300).map(f => f.path).join('\n');
  const prompt = `Architect: ${limitedTree}\nComponent: ${nodeLabel}\nQuestion: ${question}`;
  const response = await ai.models.generateContent({
       model: 'gemini-3-pro-preview',
       contents: { parts: [{ text: prompt }] }
  });
  return response.text || "Cevap üretilemedi.";
}

