import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Deep Grounding & Verification Protokolü
 * Yanlış video veya demo içerik sorununu çözmek için 'site:' operatörü kullanılır.
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO VERİLERİ SORGULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    // URL'den ID'yi temizle
    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("INVALID_URL_FORMAT");
    }

    try {
        // Prompt güncellendi: Hata fırlatmak yerine "best-effort" yaklaşımı.
        const analysisPrompt = `GÖREV: Aşağıdaki YouTube Video ID'sine sahip içeriği bul ve DİKEY MOBİL İNFOGRAFİK için detaylı analiz et.

        HEDEF VIDEO ID: ${videoId}
        LINK: ${youtubeUrl}

        ARAŞTIRMA ADIMLARI:
        1. Google Search ile "${youtubeUrl}", "${videoId}" ve "${videoId} youtube video" terimlerini ara.
        2. Arama sonuçlarındaki başlık, açıklama ve snippet'leri topla.
        3. VİDEO OYNATILAMIYOR OLSA BİLE, arama snippet'lerinden videonun konusunu çıkar.

        ÇIKTI FORMATI (${language}):
        Bu veriyi görselleştirmek için yapılandırılmış bir plan oluştur:
        - ANA BAŞLIK: (Kısa, Büyük, Vurucu - Maks 5 Kelime)
        - VİDEO ÖZETİ: (Konuyu 2 cümlede anlatan giriş metni)
        - 5-7 KRİTİK BİLGİ KARTI: Her biri bir ikon fikri ve kısa, net bir açıklama içermeli.
        - VARSA VERİLER/SAYILAR: Yüzdeler, tarihler veya istatistikler (İnfografikte büyük punto ile yazılacak).
        - SONUÇ/EYLEM ÇAĞRISI: Videonun ana fikri.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.3, 
            }
        });

        structuralSummary = analysisResponse.text || "";

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

        if (structuralSummary.length < 50) {
             structuralSummary += `\n\n(Not: Bu video için kısıtlı veri mevcuttu. Görsel, mevcut meta veriler üzerinden oluşturuldu.)`;
        }

    } catch (e: any) {
        console.warn("YouTube Deep Analysis Warning:", e.message);
        structuralSummary = `Video ID: ${videoId}. Video içeriği tam olarak doğrulanamadı, ancak isteğiniz üzerine görselleştirme oluşturuluyor. Konu: YouTube İçerik Özeti.`;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 * Gemini 3 Pro Image modeli kullanılarak 2K çözünürlükte infografik üretilir.
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR (GEMINI 3 PRO)...");

    // PROMPT GÜNCELLEMESİ: OKUNABİLİRLİK VE DETAY ODAKLI
    const imagePrompt = `DESIGN TARGET: A HIGH-DENSITY ${aspectRatio === "9:16" ? "VERTICAL (Mobile Story)" : "HORIZONTAL"} INFOGRAPHIC (2K Resolution).

    SOURCE DATA:
    ${summary}

    VISUAL STYLE: ${style}
    LANGUAGE: ${language}

    CRITICAL DESIGN RULES FOR READABILITY:
    1. **MASSIVE TYPOGRAPHY**: The Main Headline must be HUGE. Key statistics/numbers must be OVERSIZED.
    2. **READABLE TEXT BLOCKS**: Do not use small, cramped text. Use generous line height. Text must be legible on a smartphone screen without zooming.
    3. **STRUCTURED LAYOUT**: 
       - Header (Title + Intro)
       - Body (Data Visualization, List Items with Icons, Process Steps)
       - Footer (Conclusion/Source)
    4. **HIGH CONTRAST**: Ensure text pops against the background. Avoid low-contrast color combinations.
    5. **DATA VIZ**: Turn numbers into charts (Pie, Bar, or Big Number Cards).
    6. **AESTHETIC**: Professional, Clean, Vector-Art Style. No photorealism unless specified.

    Generate a complete, ready-to-publish infographic poster.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview', // En yüksek kalite model
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA DERİNLEMESİNE ANALİZ EDİLİYOR...");
    let structuralSummary = "";

    // ANALİZ PROMPTU GÜNCELLEMESİ: DETAYLI VERİ ÇIKARIMI
    const deepAnalysisPrompt = `GÖREV: Bu linkteki içeriği "Mobil Uyumlu Dikey İnfografik" tasarlamak için analiz et: ${url}.

    HEDEF: Telefon ekranında rahat okunacak, görsel ağırlıklı ve detaylı bir özet planı.

    ÇIKTI FORMATI (${language}):
    1. **VURUCU BAŞLIK**: (Kısa, net, büyük puntolara uygun)
    2. **ÖZET**: (Konunun özü, tek paragraf)
    3. **ANAHTAR VERİLER**: (Makaledeki tüm istatistikleri, tarihleri ve sayıları listele)
    4. **5-7 ÖNEMLİ MADDE**: (Konunun detaylarını madde madde, her biri için görsel önerisiyle yaz)
    5. **ALINTI**: (Varsa önemli bir cümle)
    6. **SONUÇ**: (Okuyucu ne yapmalı?)`;

    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: deepAnalysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği. Dil: ${language}.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    // Metin girdisi için de yapıyı zenginleştir
    const enrichedText = `DATA SOURCE FOR INFOGRAPHIC:\n${text}\n\nINSTRUCTION: Structure this into a high-density visual layout with a Headline, Key Stats, 5 Bullet Points, and a Conclusion.`;
    return await finalizeInfographic(enrichedText, style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [
                { inlineData: { data: fileBase64, mimeType } }, 
                { text: "GÖREV: Bu dosyanın içeriğini dikey bir infografik posteri için analiz et. Başlıklar, istatistikler, önemli maddeler ve sonuç bölümü olarak detaylı bir özet çıkar." }
            ]
        }
    });
    return await finalizeInfographic(response.text || "", style, onProgress, language, aspectRatio);
}

export async function generateInfographic(
  repoName: string, 
  fileTree: RepoFileTree[], 
  style: string, 
  is3D: boolean = false,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "16:9"
): Promise<string | null> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 150).map(f => f.path).join(', ');
  // Technical diagram prompt
  let prompt = `Teknik Mimari Diyagram: ${repoName}. Dosyalar: ${limitedTree}. Stil: ${style}. Dil: ${language}. 2K Sharp Typography.`;

  // If 3D requested, change prompt
  if (is3D) {
      prompt = `Create a futuristic 3D HOLOGRAPHIC visualization of the software architecture for ${repoName}. Glowing nodes, floating code blocks, cyberpunk aesthetic. ${style}. 2K Resolution.`;
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts: [{ text: prompt }] },
      config: {
        responseModalities: [Modality.IMAGE],
        imageConfig: { aspectRatio, imageSize: "2K" }
      },
    });
    const parts = response.candidates?.[0]?.content?.parts;
    return parts?.find(p => p.inlineData)?.inlineData?.data || null;
  } catch (error) {
    return handleApiError(error);
  }
}

