const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Hibrit Protokol (Gelişmiş Doğrulama)
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO VERİLERİ SORGULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("INVALID_URL_FORMAT");
    }

    try {
        const analysisPrompt = `ROLE: Forensic Data Analyst.
        TASK: Analyze the YouTube Video (ID: ${videoId}).

        PROTOCOL:
        1. Attempt to fetch internal video data/transcript.
        2. Use Search Tool to find "transcript for ${videoId}" or "key summary of YouTube video ${videoId}".

        STRICT REQUIREMENT:
        - If you CANNOT find meaningful content (e.g. video is private, deleted, or has no metadata/reviews), you MUST respond ONLY with the exact text: "ERROR_VIDEO_INACCESSIBLE".
        - Do NOT hallucinate a summary. 
        - Do NOT create a generic placeholder.
        - If found, extract details in ${language}.

        If successful, provide:
        - Hook, Data points, Process, Hidden Gems.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.1, // Düşük yaratıcılık, yüksek doğruluk
            }
        });

        const text = analysisResponse.text || "";

        // EĞER İÇERİK BULUNAMADIYSA SÜRECİ BURADA KES
        if (text.includes("ERROR_VIDEO_INACCESSIBLE") || text.length < 30) {
            throw new Error("VIDEO_NOT_ACCESSIBLE");
        }

        structuralSummary = text;

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

    } catch (e: any) {
        if (e.message === "VIDEO_NOT_ACCESSIBLE") {
            throw new Error("VİDEO ERİŞİLEMEZ: Bu video gizli, silinmiş veya transkript verisi internet üzerinde bulunamıyor. Lütfen bağlantıyı kontrol edin.");
        }
        throw e;
    }

    // Sadece veri varsa görsel oluşturma aşamasına geç
    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

