    SOURCE DATA: ${summary}
    STYLE: ${style}. LANG: ${language}.
    RULES: Rich typography, icons, clear layout. 2K Resolution.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
