import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Kesin Doğrulama Protokolü
 * Bu fonksiyon, video içeriğine gerçekten ulaşılmadığı sürece görsel üretmez.
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO İÇERİĞİ DOĞRULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("GEÇERSİZ_URL: Lütfen geçerli bir YouTube bağlantısı girin.");
    }

    try {
        // AŞAMA 1: İÇERİK DOĞRULAMA (GEMINI 3 PRO + SEARCH)
        const analysisPrompt = `SYSTEM INSTRUCTION: You are a strict Content Validator.
        TARGET: YouTube Video ID ${videoId} (${youtubeUrl}).

        TASK:
        1. Use Google Search Grounding to find the ACTUAL transcript, title, or detailed summary of this specific video.
        2. VERIFY: Is the video accessible? Is there metadata?

        CRITICAL FAILURE RULE:
        If the video is private, deleted, or if you cannot find specific details about its content (not just generic YouTube info), you MUST respond with exactly this text: "SIGNAL_FAILED_INACCESSIBLE".

        IF SUCCESSFUL:
        Provide a detailed technical brief for an infographic in ${language}.
        Include: Main points, statistics, key takeaways, and visual layout suggestions.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.1, // Doğruluk için düşük sıcaklık
            }
        });

        const responseText = analysisResponse.text || "";

        // Hata Kontrolü: Eğer model "erişilemez" sinyali verdiyse süreci durdur
        if (responseText.includes("SIGNAL_FAILED_INACCESSIBLE") || responseText.length < 50) {
            throw new Error("VIDEO_NOT_FOUND_OR_PRIVATE");
        }

        structuralSummary = responseText;

        // Kaynakları topla
        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

    } catch (e: any) {
        if (e.message === "VIDEO_NOT_FOUND_OR_PRIVATE") {
            throw new Error("VİDEO ANALİZ EDİLEMEDİ: Bu video gizli, silinmiş veya transkript verisi bulunamadı. Lütfen geçerli ve herkese açık bir video linki sağladığınızdan emin olun.");
        }
        throw e;
    }

    // AŞAMA 2: TASARIM (Sadece içerik varsa buraya geçer)
    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İÇERİK GÖRSELLEŞTİRİLİYOR...");

    const imagePrompt = `TASK: Create a professional 2K Infographic based on this analysis brief:

    BRIEF:
    ${summary}

    DESIGN STYLE: ${style}
    LANGUAGE: ${language}
    ASPECT RATIO: ${aspectRatio}

    REQUIREMENTS:
    - High-quality readable typography.
    - Information dense layout.
    - Professional icons and data visualization.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

// ... Diğer yardımcı fonksiyonlar (Article, Text, File) aynı kalır ...
export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA ANALİZ EDİLİYOR...");
    let structuralSummary = "";

    const deepAnalysisPrompt = `Analyze URL: ${url}. Extract Headline, Why it matters, Stats, Steps, Insights. Lang: ${language}.`;

    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: deepAnalysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
