import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - NotebookLM Tarzı Derin Analiz & Kesin Doğrulama
 * Bu fonksiyon, video içeriğine dair gerçek verilere (transkript/özet) ulaşamazsa 
 * asla görsel üretmez ve hata döner.
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("VİDEO KAYNAKLARI DERİNLİĞİNE SORGULANIYOR...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("INVALID_URL: Geçersiz YouTube bağlantısı.");
    }

    try {
        // AŞAMA 1: DERİN İÇERİK MADENCİLİĞİ (THINKING + SEARCH GROUNDING)
        // NotebookLM gibi çalışması için modele veriyi dış kaynaklardan doğrulamasını söylüyoruz.
        const analysisPrompt = `URGENT MISSION: You are a Digital Source Specialist. 
        Analyze the YouTube video: ${youtubeUrl} (ID: ${videoId}).

        STRICT VERIFICATION PROTOCOL:
        1. Use Google Search Grounding to find the ACTUAL transcript, title, and key segment summaries for this specific video.
        2. VERIFY beyond doubt that this video contains extractable content. 

        CRITICAL FAILURE CONDITIONS:
        - If the video is PRIVATE, DELETED, or HIDDEN.
        - If you cannot find a specific transcript or detailed third-party summary.
        - If you find NO data about the actual spoken content.

        IF YOU FAIL TO FIND REAL CONTENT: Respond ONLY with the token "FATAL_ERROR_SOURCE_INACCESSIBLE". Do not explain. Do not apologize.

        IF SUCCESSFUL: 
        Perform a high-density extraction in ${language}. 
        Focus on: Specific facts, metrics, chronological steps, and "hidden gems" mentioned in the video.
        Format it for a professional infographic brief.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.1, // Düşük sıcaklık = Maksimum doğruluk
                thinkingConfig: { thinkingBudget: 16000 } // NotebookLM kalitesi için düşünme bütçesi ayır
            }
        });

        const responseText = analysisResponse.text || "";

        // HATA KODU KONTROLÜ
        if (responseText.includes("FATAL_ERROR_SOURCE_INACCESSIBLE") || responseText.length < 50) {
            throw new Error("SOURCE_INACCESSIBLE");
        }

        structuralSummary = responseText;

        // Kaynak referanslarını (Citations) ayıkla
        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

    } catch (e: any) {
        if (e.message === "SOURCE_INACCESSIBLE") {
            throw new Error("ANALİZ DURDURULDU: Video içeriğine ulaşılamadı. Video gizli olabilir veya transkript verisi bulunmuyor. Boş bir infografik üretmek yerine işlemi iptal ediyoruz.");
        }
        throw e;
    }

    // AŞAMA 2: TASARIM (Sadece içerik doğrulandıysa buraya geçilir)
    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("TASARIM MOTORU ÇALIŞTIRILIYOR...");

    const imagePrompt = `TASK: Design a 2K High-Definition Infographic.
    SOURCE DATA: ${summary}
    DESIGN STYLE: ${style}. LANGUAGE: ${language}.

    VISUAL RULES:
    1. Grid-based layout.
    2. Professional iconography.
    3. Crystal clear, readable typography.
    4. Data visualization for numbers.
    5. No hallucinations; only show data from the source.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA ANALİZ EDİLİYOR...");
    let structuralSummary = "";

    const deepAnalysisPrompt = `Analyze URL: ${url}. Extract Headline, Why it matters, Stats, Steps, Insights. Lang: ${language}.`;

    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: deepAnalysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    return await finalizeInfographic(text, style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [
                { inlineData: { data: fileBase64, mimeType } }, 
                { text: `Analyze this for a ${aspectRatio} Infographic in ${language}.` }
            ]
        }
    });
    return await finalizeInfographic(response.text || "", style, onProgress, language, aspectRatio);
}

