import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
    videoTitle?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * YouTube İçerik Analizi - Gelişmiş NotebookLM Protokolü
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("BİLGİ KAYNAKLARI TARANIYOR (NOTEBOOK-LM MODE)...");

    let structuralSummary = "";
    let citations: Citation[] = [];

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) {
        throw new Error("GEÇERSİZ_BAĞLANTI: YouTube ID tespit edilemedi.");
    }

    try {
        // NOTEBOOK-LM MANTIĞI: Veriyi bulana kadar farklı kaynakları (Search Grounding) zorla
        const analysisPrompt = `CORE OBJECTIVE: Perform an exhaustive content extraction for YouTube ID: ${videoId}.

        SEARCH TASKS (Mandatory Grounding):
        1. Find the exact title and channel name of video ${videoId}.
        2. Search for "transcript of youtube video ${videoId}" or "summary of ${videoId}".
        3. Look for key takeaways, timestamps, or technical discussions related to this video on the web.

        STRICT VALIDATION:
        - If (and only if) you find absolutely NO specific data about the actual content of THIS video after searching, respond with: "FATAL_ERROR_SOURCE_INACCESSIBLE".
        - Do not provide a generic description. Be specific to the video content.

        OUTPUT SPECIFICATION:
        In ${language}, provide a high-density structured analysis:
        - Hook (The main 'Why' of the video)
        - Core Data/Steps (Chronological or thematic breakdown)
        - Crucial Metrics/Stats (If mentioned)
        - Unique Insights (The 'hidden gems')
        Format this as a detailed design brief for a 2K infographic.`;

        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: analysisPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                temperature: 0.1,
                thinkingConfig: { thinkingBudget: 24000 } // NotebookLM kalitesi için yüksek düşünme bütçesi
            }
        });

        const responseText = analysisResponse.text || "";

        if (responseText.includes("FATAL_ERROR_SOURCE_INACCESSIBLE") || responseText.length < 100) {
            throw new Error("SOURCE_INACCESSIBLE");
        }

        structuralSummary = responseText;

        const chunks = analysisResponse.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Bilgi Kaynağı" });
                }
            });
        }

    } catch (e: any) {
        if (e.message === "SOURCE_INACCESSIBLE") {
            throw new Error("ERİŞİM HATASI: Bu video içeriği (transkript/özet) genel web kaynaklarında bulunamadı. Video gizli olabilir veya NotebookLM'in özel erişim haklarına sahip olduğu bir kategoride olabilir.");
        }
        throw e;
    }

    const imgResult = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...imgResult, citations, analysisText: structuralSummary };
}

/**
 * Tasarım Finalizasyon Hattı
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("İNFOGRAFİK TASARLANIYOR (2K HD)...");

    const imagePrompt = `DESIGN BRIEF: Create a professional 2K Infographic based on this technical analysis:
    ---
    ${summary}
    ---
    STYLE: ${style}. LANGUAGE: ${language}.
    FORMAT: ${aspectRatio === "9:16" ? "Vertical Mobile" : "Horizontal Desktop"}.
    RULES: High readability, professional icons, data-dense layout, accurate typography.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                responseModalities: [Modality.IMAGE],
                imageConfig: { aspectRatio, imageSize: "2K" }
            },
        });
        const parts = response.candidates?.[0]?.content?.parts;
        const imageData = parts?.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

export async function generateArticleInfographic(
  url: string, 
  style: string, 
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("SAYFA ANALİZ EDİLİYOR...");
    let structuralSummary = "";

    const deepAnalysisPrompt = `Analyze URL: ${url}. Extract Headline, Why it matters, Stats, Steps, Insights. Lang: ${language}.`;

    try {
        const analysisResponse = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: deepAnalysisPrompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        structuralSummary = analysisResponse.text || "";
    } catch (e) {
        structuralSummary = `${url} içeriği.`;
    }
    const result = await finalizeInfographic(structuralSummary, style, onProgress, language, aspectRatio);
    return { ...result, analysisText: structuralSummary };
}

export async function generateInfographicFromText(
  text: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    return await finalizeInfographic(text, style, onProgress, language, aspectRatio);
}

export async function generateInfographicFromFile(
  fileBase64: string,
  mimeType: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16"
): Promise<InfographicResult> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: {
            parts: [
                { inlineData: { data: fileBase64, mimeType } }, 
                { text: `Analyze this for a ${aspectRatio} Infographic in ${language}.` }
            ]
        }
    });
    return await finalizeInfographic(response.text || "", style, onProgress, language, aspectRatio);
}

