export async function generateInfographic(
  repoName: string, 
  fileTree: RepoFileTree[], 
  style: string, 
  is3D: boolean = false,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "16:9",
  imageSize: "1K" | "2K" | "4K" = "1K"
): Promise<string | null> {
  const ai = getAiClient();
  const limitedTree = fileTree.slice(0, 100).map(f => f.path).join(', ');
  let prompt = `Architecture Diagram for ${repoName}. Style: ${style}. Lang: ${language}. Files: ${limitedTree}`;
  if (is3D) prompt = `3D Holographic code model of ${repoName}. ${style}.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts: [{ text: prompt }] },
    config: { imageConfig: { aspectRatio, imageSize } }
  });
  return response.candidates[0].content.parts.find(p => p.inlineData)?.inlineData?.data || null;
}

