import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * SES DÖKÜMÜ (Transcribe) - Gemini 3 Flash Preview
 */
export async function transcribeAudio(base64Audio: string, mimeType: string): Promise<string> {
    const ai = getAiClient();
    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
            parts: [
                { inlineData: { data: base64Audio, mimeType } },
                { text: "Lütfen bu ses kaydını kelimesi kelimesine metne dök. Sadece metni döndür." }
            ]
        }
    });
    return response.text || "Ses çözümlenemedi.";
}

/**
 * AGENTIC YOUTUBE ANALİZİ - Gemini 3 Pro Preview (NotebookLM Style)
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16",
  imageSize: "1K" | "2K" | "4K" = "2K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("AJAN BAŞLATILIYOR: TRANSKRİPT AVINA ÇIKILIYOR...");

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) throw new Error("GEÇERSİZ_URL: YouTube video ID'si bulunamadı.");

    // AGENTIC PROMPT: Modele önce veriyi bulması, sonra analiz etmesi talimatı veriliyor.
    const agentPrompt = `ROLE: You are an Autonomous Research Agent (NotebookLM Grade).
    TARGET: YouTube Video ID ${videoId} (${youtubeUrl}).

    MISSION PHASE 1 - RETRIEVAL:
    Use Google Search Grounding to find:
    - The EXACT transcript or closed captions of this video.
    - If transcript is missing, find detailed blog posts or summaries that quote the speaker directly.
    - Confirm the video's core technical facts and message.

    MISSION PHASE 2 - VERIFICATION:
    If you find NO specific content (only generic metadata like "Video not available" or generic channel info), you MUST fail by returning exactly: "SIGNAL_SOURCE_INACCESSIBLE".

    MISSION PHASE 3 - ANALYSIS:
    If content is verified, perform a deep structural analysis in ${language}. 
    Focus on:
    1. Primary Thesis
    2. Key Data Points/Statistics
    3. Chronological Logic Flow
    4. Practical Takeaways

    Present this as a high-fidelity information architecture for a ${imageSize} infographic.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: agentPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 } // MAKSİMUM ANALİTİK GÜÇ
            }
        });

        const summary = response.text || "";

        if (summary.includes("SIGNAL_SOURCE_INACCESSIBLE")) {
            throw new Error("VİDEO İÇERİĞİNE ULAŞILAMADI: Bu video gizli olabilir veya transkript verisi internete kapalıdır. NotebookLM gibi bir analiz için videonun halka açık transkripti olmalıdır.");
        }

        const citations: Citation[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Veri Kaynağı" });
                }
            });
        }

        const imgResult = await finalizeInfographic(summary, style, onProgress, language, aspectRatio, imageSize);
        return { ...imgResult, analysisText: summary, citations };
    } catch (e: any) {
        if (e.message.includes("ULAŞILAMADI")) throw e;
        return handleApiError(e);
    }
}

/**
 * GÖRSEL OLUŞTURMA MOTORU
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "16:9",
    imageSize: "1K" | "2K" | "4K" = "1K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress(`VERİ DOĞRULANDI. ${imageSize} TASARIM OLUŞTURULUYOR...`);

    const imagePrompt = `PRO INFOGRAPHIC DESIGN: 
    SOURCE MATERIAL: ${summary}
    DESIGN STYLE: ${style}. LANGUAGE: ${language}. 
    ASPECT RATIO: ${aspectRatio}. 
    REQUIREMENTS: Professional data visualization, readable high-end typography, consistent iconography. No hallucination, use ONLY source data.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                imageConfig: { aspectRatio, imageSize }
            },
        });
        const parts = response.candidates[0].content.parts;
        const imageData = parts.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

