/**
 * AJAN TABANLI YOUTUBE ANALİZİ (NotebookLM & Agent Mode)
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16",
  imageSize: "1K" | "2K" | "4K" = "2K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("AJAN BAŞLATILDI: TRANSKRİPT VE KAYNAK AVINA ÇIKILIYOR...");

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) throw new Error("GEÇERSİZ_URL: YouTube video ID tespit edilemedi.");

    // AJAN TALİMATI: Veriyi bul, doğrula ve yapılandır.
    const agentPrompt = `AUTONOMOUS AGENT TASK: Deep Analysis of Video ID: ${videoId}.

    STEP 1: Use Google Search to find the EXACT TRANSCRIPT or detailed text summary of this specific video.
    STEP 2: Identify the main speaker, core arguments, technical data, and conclusion.
    STEP 3: If NO REAL CONTENT is found (only metadata), return: "FATAL_ERROR_NO_SOURCE".

    If successful, generate a dense information architecture in ${language} for a 4K infographic brief.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: agentPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 } // MAKSİMUM AKIL YÜRÜTME
            }
        });

        const summary = response.text || "";
        if (summary.includes("FATAL_ERROR_NO_SOURCE")) {
            throw new Error("KAYNAK BULUNAMADI: Ajan videonun transkriptini veya detaylı özetini web üzerinde bulamadı. Video gizli olabilir.");
        }

        const citations: Citation[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

        const imgResult = await finalizeInfographic(summary, style, onProgress, language, aspectRatio, imageSize);
        return { ...imgResult, analysisText: summary, citations };
    } catch (e: any) {
        if (e.message.includes("BULUNAMADI")) throw e;
        return handleApiError(e);
    }
}

/**
 * GÖRSEL TASARIM MOTORU
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "16:9",
    imageSize: "1K" | "2K" | "4K" = "1K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress(`${imageSize} İNFOGRAFİK TASARLANIYOR...`);

    const imagePrompt = `PROFESSIONAL INFOGRAPHIC BRIEF: 
    DATA SOURCE: ${summary}
    VISUAL STYLE: ${style}. LANGUAGE: ${language}. 
    QUALITY: ${imageSize} Ultra HD.
    LAYOUT: ${aspectRatio}.
    RULES: Crystal clear text, professional icons, logically mapped data flow.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                imageConfig: { aspectRatio, imageSize }
            },
        });
        const parts = response.candidates[0].content.parts;
        const imageData = parts.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

