  const [loadingStage, setLoadingStage] = useState('');
  const [fullScreenImage, setFullScreenImage] = useState<{src: string, alt: string} | null>(null);

  useEffect(() => {
    if (error) {
        setError(null);
        setErrorCode(null);
    }
  }, [urlInput]);

  const videoId = useMemo(() => {
    if (!urlInput) return null;
    const input = urlInput.trim();
    const standardRegex = /(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?|shorts)\/|.*[?&]v=)|youtu\.be\/|youtube\.com\/embed\/)([a-zA-Z0-9_-]{11})/i;
    const match = input.match(standardRegex);
    if (match && match[1]) return match[1];
    if (input.length === 11 && /^[a-zA-Z0-9_-]{11}$/.test(input)) return input;
    return null;
  }, [urlInput]);

  const cleanUrl = useMemo(() => {
    if (!videoId) return urlInput;
    return `https://www.youtube.com/watch?v=${videoId}`;
  }, [videoId, urlInput]);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!videoId) {
        setError("Lütfen geçerli bir YouTube video linki veya ID'si girin.");
        return;
    }

    setLoading(true);
    setError(null);
    setErrorCode(null);
    setImageData(null);
    setAnalysisText(null);
    setCitations([]);

    try {
      const result = await generateYoutubeInfographic(cleanUrl, selectedStyle, (s) => setLoadingStage(s), selectedLanguage, aspectRatio, imageSize);

      if (result && result.imageData) {
          setImageData(result.imageData);
          setAnalysisText(result.analysisText || null);
          setCitations(result.citations || []);
      }
