/**
 * AJAN TABANLI YOUTUBE ANALİZİ (Learning App Mantığı)
 */
export async function generateYoutubeInfographic(
  youtubeUrl: string,
  style: string,
  onProgress?: (stage: string) => void,
  language: string = "Turkish",
  aspectRatio: "16:9" | "9:16" = "9:16",
  imageSize: "1K" | "2K" | "4K" = "2K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress("ÖĞRENME AJANI BAŞLATILDI: TRANSKRİPT VERİSİ ARANIYOR...");

    const videoIdMatch = youtubeUrl.match(/(?:v=|\/embed\/|\/shorts|live\/|youtu\.be\/|v\/|^)([a-zA-Z0-9_-]{11})/);
    const videoId = videoIdMatch ? videoIdMatch[1] : null;

    if (!videoId) throw new Error("GEÇERSİZ_URL: Video ID bulunamadı.");

    // LEARNING AGENT PROMPT: Transkript odaklı, eğitim materyali formatında analiz.
    const agentPrompt = `ROLE: Educational Research Agent.
    TARGET: YouTube Video ID: ${videoId}.

    INSTRUCTIONS:
    1. EXTRACT TRANSCRIPT: Use Google Search Grounding to find the full transcript or verbatim text content of this video.
    2. ANALYZE CONTENT: Structure the content as a "Learning Module". 
       - Core Concept
       - Key Definitions
       - Detailed Steps/Explanation
       - Crucial Statistics
       - Practical Summary
    3. LANGUAGE: Perform all analysis in ${language}.
    4. ERROR: If no specific data found, return "SOURCE_DATA_MISSING".

    Format the output as a high-density structured text report for a 4K infographic.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: agentPrompt,
            config: { 
                tools: [{ googleSearch: {} }],
                thinkingConfig: { thinkingBudget: 32768 } // MAKSİMUM ÖĞRENME KAPASİTESİ
            }
        });

        const summary = response.text || "";
        if (summary.includes("SOURCE_DATA_MISSING")) {
            throw new Error("VİDEO İÇERİĞİ ÇÖZÜMLENEMEDİ: Ajan bu videonun transkriptini web üzerinde bulamadı.");
        }

        const citations: Citation[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }

        const imgResult = await finalizeInfographic(summary, style, onProgress, language, aspectRatio, imageSize);
        return { ...imgResult, analysisText: summary, citations };
    } catch (e: any) {
        if (e.message.includes("ÇÖZÜMLENEMEDİ")) throw e;
        return handleApiError(e);
    }
}

/**
 * GÖRSEL TASARIM MOTORU
 */
async function finalizeInfographic(
    summary: string,
    style: string,
    onProgress?: (stage: string) => void,
    language: string = "Turkish",
    aspectRatio: "16:9" | "9:16" = "16:9",
    imageSize: "1K" | "2K" | "4K" = "1K"
): Promise<InfographicResult> {
    const ai = getAiClient();
    if (onProgress) onProgress(`VERİ ANALİZ EDİLDİ. ${imageSize} ÖĞRENME MATERYALİ TASARLANIYOR...`);

    const imagePrompt = `EDUCATIONAL INFOGRAPHIC: 
    LEARNING CONTENT: ${summary}
    STYLING: ${style}. LANGUAGE: ${language}. 
    QUALITY: ${imageSize} Professional UHD.
    LAYOUT: ${aspectRatio}.
    RULES: High readability for students, professional diagramming, accurate transcription-based notes.`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-image-preview',
            contents: { parts: [{ text: imagePrompt }] },
            config: { 
                imageConfig: { aspectRatio, imageSize }
            },
        });
        const parts = response.candidates[0].content.parts;
        const imageData = parts.find(p => p.inlineData)?.inlineData?.data || null;
        return { imageData, citations: [] };
    } catch (error) {
        return handleApiError(error);
    }
}

