            </form>
        </div>

        {/* SAĞ: SONUÇLAR (TRANSKRİPT VE İNFOGRAFİK) */}
        <div className="space-y-8 h-full">
            {loading && <div className="py-20"><LoadingState message={loadingStage} type="article" /></div>}

            {imageData && !loading && (
