import { GoogleGenAI, Type, Modality } from "@google/genai";
import { RepoFileTree, Citation } from '../types';

const getAiClient = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export interface InfographicResult {
    imageData: string | null;
    citations: Citation[];
    analysisText?: string;
}

export interface PresentationOutline {
    title: string;
    slides: { title: string; content: string; keyPoints: string[] }[];
    citations: Citation[];
}

const handleApiError = (error: any) => {
    console.error("Gemini API Error:", error);
    if (error?.message?.includes("Requested entity was not found")) {
        window.dispatchEvent(new CustomEvent('reset-api-key'));
    }
    throw error;
};

/**
 * SUNUM TASLAĞI OLUŞTURUCU - Gemini 3 Pro
 */
export async function generatePresentationOutline(topic: string, language: string = "Turkish"): Promise<PresentationOutline> {
    const ai = getAiClient();
    const prompt = `ROLE: Advanced Presentation Strategist.
    TOPIC: ${topic}.
    LANGUAGE: ${language}.

    TASK: 
    1. Research current data/trends on this topic using Google Search.
    2. Create a high-impact presentation outline with 7-10 slides.
    3. Each slide must have a title, short descriptive paragraph, and 3 key bullet points.

    Format output strictly as JSON following this schema:
    {
        "title": "Presentation Main Title",
        "slides": [
            { "title": "Slide Title", "content": "Brief overview", "keyPoints": ["point 1", "point 2", "point 3"] }
        ]
    }
    `;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: { 
                tools: [{ googleSearch: {} }],
                responseMimeType: "application/json",
                thinkingConfig: { thinkingBudget: 32768 }
            }
        });

        const data = JSON.parse(response.text || "{}");
        const citations: Citation[] = [];
        const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
        if (chunks) {
            chunks.forEach((chunk: any) => {
                if (chunk.web?.uri) {
                    citations.push({ uri: chunk.web.uri, title: chunk.web.title || "Kaynak" });
                }
            });
        }
        return { ...data, citations };
    } catch (e: any) {
        return handleApiError(e);
    }
}

